test('RISK DEVICE STORAGE V2: conditional pending writes refuse JSON-lossy unknown evidence',async t=>{
 for(const shape of ['negative zero','sparse array with property'])await t.test(shape,async sub=>{
  const {IDBFactory}=await import('fake-indexeddb'),indexedDB=new IDBFactory(),deviceDbName='pending-lossy-shape-'+Math.random();
  const store=loadStorageV2({indexedDB}).createDeviceStore({indexedDB,crypto:webcrypto,dbName:deviceDbName});await store.open();sub.after(()=>store.close());
  const common={generationId:'original',payloadHash:'a'.repeat(64),baseRev:6,updatedAt:1,account:'owner'};let original,expected;
  if(shape==='negative zero'){original={...common,futurePending:-0};expected={...common,futurePending:0};}
  else{const items=new Array(1);items.future='sole unknown pending evidence';original={...common,futurePending:items};expected={...common,futurePending:[null]};}
  await editRawDevice187(indexedDB,deviceDbName,tx=>tx.objectStore('meta').put(original,'pending:owner'));const before=await store.readRawExportSnapshot();
  const result=await store.setPendingUploadIfCurrent('owner',{generationId:'replacement',payloadHash:'b'.repeat(64),baseRev:6,updatedAt:2},expected);
  assert.equal(result.ok,undefined,'distinct physical unknown evidence cannot compare equal through JSON conversion');
  assert.deepEqual(await store.readRawExportSnapshot(),before,'unsupported complete rows remain exact');
 });
});

test('RISK cloud source recovery pending capture: native recovery cannot discard a named array extension',async t=>{
 const app=await divergentCloudSourceApp187(t),{ctx,backend,originalRoot}=app,store=ctx.window.ScannerDeviceStore;
 const gen=originalRoot.previousGeneration,header=backend.docs.get('users/owner/generations/'+gen),future=new Array(1),marker='SOLE-UNKNOWN-PENDING-ARRAY-EVIDENCE';future.future=marker;
 const pending={generationId:gen,payloadHash:header.hash,baseRev:header.baseRev,updatedAt:1,account:'owner',futurePending:future};
 await editRawDevice187(app.indexedDB,app.deviceDbName,tx=>tx.objectStore('meta').put(pending,'pending:owner'));
 assert.equal((await store.getPendingUpload('owner')).futurePending.future,marker);
 assert.equal(await ctx.onAction('review-cloud-source-recovery',{}),true);assert.equal(await ctx.onAction('choose-cloud-recovery-source',{dataset:{value:'device'}}),true);
 const result=await ctx.onAction('apply-cloud-source-recovery',{});
 assert.equal(result,false,'a choice whose pending original cannot be represented losslessly stays held');
 assert.equal(backend.docs.get('users/owner').rev,originalRoot.rev,'no publication may precede this source validation');
 assert.equal((await store.getPendingUpload('owner')).futurePending.future,marker,'the sole unknown evidence remains in its exact original physical row');
});


async function damagedAcknowledgedApp187(t,{timeoutMs=5000,sourcePadding=0,timerProvider=null,recoveryTimeoutMs=timeoutMs}={}){
 const fixture=heldDecisionFixture188();
 if(sourcePadding)fixture.remote.futureIOSReportFixture={opaque:'q'.repeat(sourcePadding)};
 fixture.local=structuredClone(fixture.remote);
 const faults={},app=await heldDecisionApp188(t,{fixture,failures:faults,timeoutMs,timerProvider,recoveryTimeoutMs}),{ctx,shim,backend}=app;
 ctx.window.CLOUD_PUSH_DELAY_MS=60000;
 shim.document.getElementById('addInput').value='Acknowledged before source damage';
 await ctx.onAction('add',{});assert.equal(await ctx.persist(),true);
 await ctx.sendPush();await settleRecovery188(app);
 shim.document.getElementById('addInput').value='Second acknowledged source';
 await ctx.onAction('add',{});assert.equal(await ctx.persist(),true);
 await ctx.sendPush();await settleRecovery188(app);
 const originalRoot={...backend.docs.get('users/owner')};
 assert.equal(originalRoot.schemaVersion,2,'the setup must produce a real chunk-generation ACK');
 const originalHeader={...backend.docs.get('users/owner/generations/'+originalRoot.activeGeneration)};
 const acknowledged=ctx.state.decisionBase.payload;
 assert.equal(createHash('sha256').update(acknowledged,'utf8').digest('hex'),originalHeader.hash,'the retained source is independently proved byte exact');
 const acknowledgedTasks=JSON.parse(acknowledged).tasks;
 const previousPath='users/owner/generations/'+originalRoot.previousGeneration;
 const previousSource=[...backend.docs].filter(([key])=>key===previousPath||key.startsWith(previousPath+'/')).map(([key,value])=>[key,JSON.stringify(value)]);
 assert.ok(previousSource.length>1,'the damaged root also names a complete previous source');
 for(const key of [...backend.docs.keys()])if(key.startsWith('users/owner/generations/'+originalRoot.activeGeneration+'/chunks/'))backend.docs.delete(key);
 return {...app,faults,originalRoot,originalHeader,acknowledgedTasks,previousSource};
}

test('RISK iOS source replay: an exact acknowledged board repairs missing current chunks after a cold reopen without a new edit',async t=>{
 const app=await damagedAcknowledgedApp187(t,{sourcePadding:2000000}),{backend,originalRoot,originalHeader,indexedDB,deviceDbName}=app;
 await closeLegacyApp173(app);backend.CS.suspend();
 const cold=await loadAppAtTime(1792323000000,{sharedStorage:app.shim.localStorage,indexedDBProvider:indexedDB,deviceDbName});t.after(()=>closeLegacyApp173(cold));
 const reader=await loadCloudBackendV2({runtimeWindow:cold.ctx.window,failures:{authPending:true},timeoutMs:5000});t.after(()=>reader.CS.suspend());
 for(const [key,value]of backend.docs)reader.docs.set(key,value);
 const ack=cold.ctx.state.decisionBase.payload;
 assert.equal(createHash('sha256').update(ack,'utf8').digest('hex'),originalHeader.hash,'cold-open bytes independently match the damaged current generation');
 assert.equal(Buffer.byteLength(ack,'utf8'),originalHeader.byteLength,'the retained source has the exact declared byte length');
 reader.emitAuth({uid:'owner',email:'e@example.com'});await cold.ctx.cloudPull();await cold.ctx.sendPush();
 const {remote,head}=await settleRecovery188({...cold,backend:reader});
 assert.ok(remote.rev>originalRoot.rev,'repair obtains an actual later revision ACK without needing a fresh task');
 assert.deepEqual(JSON.parse(remote.payload).tasks,app.acknowledgedTasks);
 assert.equal(JSON.parse(remote.payload).futureIOSReportFixture.opaque.length,2000000);
 assert.equal(head.payload,JSON.stringify(cold.ctx.state));
 const root=reader.docs.get('users/owner'),path='users/owner/generations/'+root.activeGeneration,header=reader.docs.get(path),chunks=[...reader.docs].filter(([key])=>key.startsWith(path+'/chunks/')).map(([,row])=>row).sort((a,b)=>a.index-b.index);
 assert.equal(await cold.ctx.window.ChainStorageV2.decodeSnapshot(header,chunks),remote.payload,'repair publishes a complete independently decodable generation');
 for(const [key,raw]of app.previousSource)assert.equal(JSON.stringify(reader.docs.get(key)),raw,'the older original stays exact');
 const peer=await loadAppAtTime(1792323000000,{indexedDBProvider:indexedDB,deviceDbName:deviceDbName+'-independent-receiver'});t.after(()=>closeLegacyApp173(peer));
 const receiving=await loadCloudBackendV2({runtimeWindow:peer.ctx.window,failures:{authPending:true},timeoutMs:5000});t.after(()=>receiving.CS.suspend());for(const [key,value]of reader.docs)receiving.docs.set(key,value);
 receiving.emitAuth({uid:'owner',email:'e@example.com'});await peer.ctx.cloudPull();
 assert.deepEqual(JSON.parse(JSON.stringify(peer.ctx.state.tasks)),app.acknowledgedTasks,'an isolated ordinary receiving client accepts every serialized field of the repaired board');
 assert.equal(peer.ctx.state.futureIOSReportFixture.opaque.length,2000000);
});

test('RISK iOS source replay: a modal opened during exact-copy inspection defers repair and closing resumes without an edit',async t=>{
 const app=await damagedAcknowledgedApp187(t),{ctx,shim,backend,originalRoot}=app;
 const before=JSON.stringify(ctx.state),head=await ctx.window.ScannerDeviceStore.readHead(),pending=await ctx.window.ScannerDeviceStore.getPendingUpload('owner');
 const query=shim.document.querySelector.bind(shim.document);shim.document.querySelector=selector=>selector==='.mback, dialog[open]'&&shim.document.getElementById('modalRoot').innerHTML?{}:query(selector);
 const currentPath='users/owner/generations/'+originalRoot.activeGeneration,previousPath='users/owner/generations/'+originalRoot.previousGeneration,gate=deferredSyncFixture();let reads=0,entered=false,pull;
 app.faults.serverRead=async path=>{if(path===currentPath&&++reads>=2||path===previousPath){entered=true;await gate.promise;}};
 t.after(async()=>{gate.resolve();delete app.faults.serverRead;await pull;});
 pull=ctx.cloudPull();await fixtureDeadline((async()=>{while(!entered)await flush();})(),'automatic exact-copy source inspection enters after the ordinary corrupt-generation read');
 ctx.openHelp();assert.match(shim.document.getElementById('modalRoot').innerHTML,/Quick start/);gate.resolve();await pull;
 assert.equal(backend.docs.get('users/owner').rev,originalRoot.rev,'opening a modal cannot authorize a source swap');
 assert.equal(ctx.buildSupportDiagnosticsReport().recoverySources.exactAcknowledgedCopy.matchesCurrentGeneration.status,'unobserved','an interrupted eligibility check is not a negative match');
 assert.equal(JSON.stringify(ctx.state),before);assert.equal((await ctx.window.ScannerDeviceStore.readHead()).hash,head.hash);assert.deepEqual(await ctx.window.ScannerDeviceStore.getPendingUpload('owner'),pending);
 t.diagnostic(JSON.stringify({probe:'ACK-modal-resume',deferred:vm.runInContext('deferredCloudPull',ctx),pulling:vm.runInContext('pulling',ctx),retryPending:vm.runInContext('!!cloudRetryTimer',ctx),headUnchanged:true,pendingUnchanged:true,stateUnchanged:true,cloudRevUnchanged:true}));
 delete app.faults.serverRead;await ctx.onAction('close-modal',{});
 const {remote}=await settleRecovery188(app);
 assert.ok(remote.rev>originalRoot.rev,'safe close resumes exact repair without requiring a new accepted task');
 assert.deepEqual(JSON.parse(remote.payload).tasks,app.acknowledgedTasks);
 ctx.openHelp();assert.match(shim.document.getElementById('modalRoot').innerHTML,/Closing a dialog that paused an exact-copy check starts a fresh safe check; no new task is needed/);
 assert.match(html,/Closing a dialog resumes a paused exact-copy repair check without another edit/);
});

function recoveryReadClock187(){
 let active=false,elapsed=0,next=0,ctx;const start=1792323000000,timers=new Map(),scheduled=[];
 const provider={Date:class extends Date{static now(){return active?start+elapsed:Date.now();}},performance:{now:()=>elapsed},
  setTimeout(fn,delay,...args){if(!active)return setTimeout(fn,delay,...args);const id={recoveryClock187:++next};timers.set(id,{fn:()=>fn(...args),at:elapsed+Number(delay),delay:Number(delay)});scheduled.push(Number(delay));return id;},
  clearTimeout(id){if(timers.has(id))timers.delete(id);else clearTimeout(id);}};
 return {provider,timers,scheduled,get elapsed(){return elapsed;},activate(app){ctx=app.ctx;active=true;ctx.setTimeout=provider.setTimeout;ctx.clearTimeout=provider.clearTimeout;ctx.performance=provider.performance;setFakeTime(ctx,start);},
  async advance(ms){const target=elapsed+ms;while(true){const due=[...timers].filter(([,timer])=>timer.at<=target).sort((a,b)=>a[1].at-b[1].at)[0];if(!due)break;elapsed=due[1].at;setFakeTime(ctx,start+elapsed);timers.delete(due[0]);due[1].fn();await flush();}elapsed=target;setFakeTime(ctx,start+elapsed);await flush();},
  stop(){active=false;timers.clear();}};
}

test('RISK cloud source fresh check: one between-capture cloud change verifies again within the same review',async t=>{
 const app=await divergentCloudSourceApp187(t),{ctx,shim,backend}=app,store=ctx.window.ScannerDeviceStore;
 await fixtureDeadline((async()=>{while(true){const save=ctx.buildSupportDiagnosticsReport().save;if(!save.debouncePending.value&&!save.activePersistCalls.value)return;await flush();}})(),'fixture saves finish before measuring source preservation');
 const before=JSON.stringify(ctx.state),head=await store.readHead(),pending=await store.getPendingUpload('owner'),raw=await store.readRawExportSnapshot(),writes=backend.writes.length;
 let roots=0,expectedCloud=JSON.stringify([...backend.docs]);
 app.faults.serverRead=async path=>{if(path==='users/owner'&&++roots===3){backend.docs.set(path,{...backend.docs.get(path),rev:app.originalRoot.rev+1});expectedCloud=JSON.stringify([...backend.docs]);}};
 t.after(()=>{delete app.faults.serverRead;});
 assert.equal(await ctx.onAction('review-cloud-source-recovery',{}),true,'one transient peer change reaches a fresh verified preview in the same user attempt');
 const modal=shim.document.getElementById('modalRoot').innerHTML;
 assert.match(modal,/data-act="choose-cloud-recovery-source"/);assert.doesNotMatch(modal,/data-act="choose-cloud-recovery-source"[^>]*aria-pressed="true"/);
 assert.match(modal,/data-act="apply-cloud-source-recovery"[^>]*disabled/);assert.equal(roots,8,'one restart reads two entirely fresh complete captures');
 assert.equal(JSON.stringify(ctx.state),before);assert.deepEqual(await store.readHead(),head);assert.deepEqual(await store.getPendingUpload('owner'),pending);
 assert.deepEqual(await store.readRawExportSnapshot(),raw);assert.equal(JSON.stringify([...backend.docs]),expectedCloud);assert.equal(backend.writes.length,writes,'verification never publishes or selects a source');
 let download=null,blob=null;const link=makeFakeElement();link.remove=()=>{};link.click=()=>{download=blob;};
 shim.document.createElement=tag=>tag==='a'?link:makeFakeElement();ctx.Blob=class{constructor(parts){blob=parts.join('');}};
 ctx.URL={createObjectURL(){return 'blob:fresh-source-diagnostics';},revokeObjectURL(){}};
 ctx.onAction('view-support-diagnostics',{});await ctx.onAction('download-support-diagnostics',{});assert.equal(typeof download,'string');
 const report=JSON.parse(download),operations=report.sourceOperations;
 assert.equal(report.metadataOnly,true);assert.equal(report.boardDataIncluded,false);assert.ok(Buffer.byteLength(download,'utf8')<=24*1024);assert.ok(report.events.length<=80);assert.ok(operations.length<=8);
 assert.equal(report.retention.truncated.value,true,'compacted diagnostic detail is explicitly disclosed');assert.ok(report.retention.dropped.value>0);
 assert.equal(operations.filter(operation=>operation.status==='stale').length,1,'the report retains the original cross-capture refusal after automatic recovery: '+JSON.stringify(operations.map(operation=>({alias:operation.alias,status:operation.status,events:operation.events.map(event=>event.stage+":"+event.status)}))));
 assert.equal(operations.filter(operation=>operation.status==='completed').length,1,'the fresh verification has a separate completed operation');
 assert.ok(operations[0].events.some(event=>event.stage==='source-read'&&event.status==='stale'));
 assert.doesNotMatch(download,/owner|generationId|Fixture A|Device source only/,'the actual downloaded retry trace stays redacted');
 assert.equal(JSON.stringify(ctx.state),before);assert.deepEqual(await store.readHead(),head);assert.deepEqual(await store.getPendingUpload('owner'),pending);assert.deepEqual(await store.readRawExportSnapshot(),raw);assert.equal(backend.writes.length,writes);
});

async function settleSourceFixtureSave187(app,message,requireDurable=false){
 const end=Date.now()+5000;
 while(Date.now()<end){
  const save=app.ctx.buildSupportDiagnosticsReport().save;
  if(!save.debouncePending.value&&!save.activePersistCalls.value&&(!requireDurable||save.localDurability.value==='durable'&&save.durableThroughRequest.value>=save.acceptedRequests.value))return;
  await flush();
 }
 const timer=vm.runInContext('saveTimer',app.ctx);throw Error(message+'; startup save observations '+JSON.stringify(app.ctx.buildSupportDiagnosticsReport().save)+'; timer '+inspect(timer,{depth:0}));
}
async function freshSourceCheckFixture187(t,options={}){
 const app=await divergentCloudSourceApp187(t,{...options,settleDeviceBeforeCloud:true});
 app.ctx.window.CLOUD_PUSH_DELAY_MS=60000;
 await settleSourceFixtureSave187(app,'fixture saves finish before fresh-check controls');
 return app;
}

