  const w=sampler.createWorld(()=>0);w.events=[];w.next=Infinity;w.railNext={train:Infinity,metro:Infinity};w.nextFestival=type==='festival'?0:Infinity;w.nextFireworks=type==='fireworks'?0:Infinity;
