test("PWA contract: service worker precaches the app and uses a cache-first fetch strategy", () => {
  const match = html.match(/navigator\.serviceWorker\.register\(\s*["']([^"']+)["']/);
  assert.ok(match, "service-worker source path must be discoverable from the app registration");
  const workerPath = path.resolve(__dirname, match[1]);
  assert.ok(fs.existsSync(workerPath), `service-worker source must exist: ${match[1]}`);
  const worker = fs.readFileSync(workerPath, "utf8");

  assert.match(worker, /addEventListener\(\s*["']install["']/,
    "service worker must install a cache");
  assert.match(worker, /caches\.open\(/, "service worker must open a named cache");
  assert.match(worker, /\.addAll\(\s*\[/, "service worker must precache the app shell");
  assert.match(worker, /addEventListener\(\s*["']fetch["']/,
    "service worker must handle fetches");
  assert.match(worker, /event\.respondWith\(/,
    "fetch handling must control the response with event.respondWith()");
  assert.match(worker, /caches\.match\(/, "fetch handling must check the cache first");
  assert.match(worker, /caches\.match\(\s*event\.request\s*,\s*\{\s*cacheName\s*:\s*CACHE_NAME\s*\}\s*\)[\s\S]{0,240}\|\|\s*fetch\(\s*event\.request\s*\)/,
    "fetch handling must return the cached response before falling back to the network request");
  assert.match(worker, /addEventListener\(\s*["']activate["']/,
    "service worker must activate and retire old shell caches");
  assert.match(worker, /clients\.claim\(\)/, "service worker must claim already-open app clients");
  assert.match(worker, /caches\.match\(\s*["']\.\/index\.html["']\s*,\s*\{\s*cacheName\s*:\s*CACHE_NAME\s*\}\s*\)/,
    "failed navigations must fall back to the cached app shell");
});

function serviceWorkerSource() {
  const match = html.match(/navigator\.serviceWorker\.register\(\s*["']([^"']+)["']/);
  assert.ok(match, "service-worker source path must be discoverable from the app registration");
  const workerPath = path.resolve(__dirname, match[1]);
  assert.ok(workerPath.startsWith(`${__dirname}${path.sep}`), "service worker must stay inside the app repository");
  return fs.readFileSync(workerPath, "utf8");
}

function appShellContract(worker) {
  const cacheMatch = worker.match(/const\s+CACHE_NAME\s*=\s*["']([^"']+)["']/);
  assert.ok(cacheMatch, "service worker must declare a literal CACHE_NAME");

  const addAllMatch = worker.match(/\.addAll\(\s*\[([\s\S]*?)\]/);
  assert.ok(addAllMatch, "service worker must precache a literal app-shell path list");
  const rawPaths = [...addAllMatch[1].matchAll(/["']([^"']+)["']/g)].map((match) => match[1]);
  assert.ok(rawPaths.length > 0, "service worker app-shell path list must not be empty");

  const localPaths = [...new Set(rawPaths.flatMap((entry) => {
    // Remote URLs are intentionally not part of the local shell fingerprint.
    if (/^(?:[a-z][a-z\d+.-]*:)?\/\//i.test(entry) || /^[a-z][a-z\d+.-]*:/i.test(entry)) return [];
    const normalized = path.posix.normalize(entry.replace(/^\.\//, ""));
    // The root navigation and its explicit HTML fallback are the same shell file.
    if (normalized === "." || normalized === "index.html") return ["index.html"];
    // A worker cannot fingerprint itself without creating a circular release key.
    if (normalized === "sw.js") return [];
    return [normalized];
  }))].sort();
  assert.ok(localPaths.includes("index.html"), "app-shell fingerprint must include index.html");

  const hash = createHash("sha256");
  for (const relativePath of localPaths) {
    const absolutePath = path.resolve(__dirname, relativePath);
    assert.ok(absolutePath.startsWith(`${__dirname}${path.sep}`),
      `precached local asset must stay inside the app repository: ${relativePath}`);
    assert.ok(fs.existsSync(absolutePath), `precached local asset must exist: ${relativePath}`);
    hash.update(relativePath);
    hash.update("\0");
    hash.update(fs.readFileSync(absolutePath));
    hash.update("\0");
  }

  return {
    cacheName: cacheMatch[1],
    rawPaths,
    localPaths,
    fingerprint: hash.digest("hex"),
  };
}

test("PWA cache contract: CACHE_NAME is mechanically tied to every local app-shell byte", () => {
  const { cacheName, fingerprint } = appShellContract(serviceWorkerSource());
  assert.equal(cacheName, `chain-scanner-shell-${fingerprint}`,
    "changing any locally precached shell asset must require a corresponding cache-key update");
});

function serviceWorkerHarness(worker, existingCacheNames = []) {
  const handlers = {};
  const cacheRecords = new Map(existingCacheNames.map((name) => [name, { added: [] }]));
  let skipWaitingCalls = 0;
  let claimCalls = 0;
  const caches = {
    open(name) {
      if (!cacheRecords.has(name)) cacheRecords.set(name, { added: [] });
      const record = cacheRecords.get(name);
      return Promise.resolve({
        addAll(entries) {
          record.added.push(...entries);
          return Promise.resolve();
        },
        put() { return Promise.resolve(); },
      });
    },
    keys() { return Promise.resolve([...cacheRecords.keys()]); },
    delete(name) { return Promise.resolve(cacheRecords.delete(name)); },
    match() { return Promise.resolve(undefined); },
  };
  const context = {
    caches,
    console,
    fetch() { return Promise.reject(new Error("network should not be used in lifecycle test")); },
    URL,
    Request: class { constructor(url, options){ this.url=url; this.cache=options.cache; } },
    self: {
      location: { origin: "https://scanner.example" },
      addEventListener(type, handler) { handlers[type] = handler; },
      skipWaiting() { skipWaitingCalls += 1; return Promise.resolve(); },
      clients: { claim() { claimCalls += 1; return Promise.resolve(); } },
    },
  };
  vm.runInNewContext(worker, context, { filename: "sw.js" });
  return { handlers, cacheRecords, skipWaitingCalls: () => skipWaitingCalls, claimCalls: () => claimCalls };
}

test('RISK PWA release metadata: exact scoped identity bypasses stale shell cache',async()=>{
 for(const {origin,basePath} of [
  {origin:'https://chain-scanner.web.app',basePath:'/'},
  {origin:'https://emerald-pham.github.io',basePath:'/funsidething/'},
 ]){
  const handlers={},cacheReads=[],networkRequests=[];let online=true;
  const caches={match:async request=>{cacheReads.push(new URL(request.url).pathname);return new Response('stale shell metadata');}};
  const worker=serviceWorkerSource(),scope=origin+basePath;
  vm.runInNewContext(worker,{caches,URL,Request,fetch:async request=>{
   const url=new URL(request.url);networkRequests.push(url.href);if(!online)throw Error('offline');return new Response('fresh metadata');
  },self:{location:{origin},registration:{scope},addEventListener(type,handler){handlers[type]=handler;},clients:{claim(){return Promise.resolve();}}}},{filename:'sw.js'});
  const request=async url=>{let response;handlers.fetch({request:new Request(url),respondWith(value){response=value;}});assert.ok(response,'the service worker handles same-origin GETs');return response;};
  const metadataUrl=new URL('channel-release.json?release=one',scope).href;
  const fresh=await request(metadataUrl);
  assert.equal(await fresh.text(),'fresh metadata','a cached envelope must never identify the running release');
  assert.deepEqual(cacheReads,[],'the exact scoped metadata request skips cache lookup');
  online=false;
  await assert.rejects(request(new URL('channel-release.json?release=offline',scope).href),/offline/,'offline metadata has no stale shell fallback');
  assert.deepEqual(cacheReads,[],'metadata remains network-only when the network fails');
  const shell=await request(new URL('index.html',scope).href);
  assert.equal(await shell.text(),'stale shell metadata','ordinary shell assets retain the existing cache-first behavior');
  assert.equal(cacheReads.length,1,'only the ordinary shell request consulted the cache');
  assert.equal(networkRequests.length,2,'both metadata requests reached the network; the offline ordinary cached shell did not');
 }
});

test("PWA lifecycle: shell waits for prior clients and normal activation retires prior caches", async () => {
  const worker = serviceWorkerSource();
  const { cacheName, rawPaths } = appShellContract(worker);
  const harness = serviceWorkerHarness(worker, ["chain-scanner-shell-v1", "unrelated-cache"]);

  const installWaits = [];
  harness.handlers.install({ waitUntil(promise) { installWaits.push(promise); } });
  await Promise.all(installWaits);
  assert.deepEqual(harness.cacheRecords.get(cacheName).added.map(request=>request.url), rawPaths,
    "install must precache the exact current app-shell path list");
  assert.equal(harness.skipWaitingCalls(), 0, "install must let the browser wait for already-open clients to close");

  const activateWaits = [];
  harness.handlers.activate({ waitUntil(promise) { activateWaits.push(promise); } });
  await Promise.all(activateWaits);
  assert.equal(harness.cacheRecords.has("chain-scanner-shell-v1"), false,
    "activation must delete the previous shell cache");
  assert.equal(harness.cacheRecords.has(cacheName), true,
    "activation must retain the current fingerprinted shell cache");
  assert.equal(harness.cacheRecords.has("unrelated-cache"), true,
    "activation must leave unrelated caches alone");
  assert.equal(harness.claimCalls(), 1, "activation must claim already-open app clients");
});

test("RISK PWA module delivery: a fresh installed shell serves every production script while offline", async () => {
  const releasedWorker = spawnSync('git', ['show', '48b9c58aa03b4d2c7006358f70466f590e685543:sw.js'], { cwd: __dirname, encoding: 'utf8' });
  assert.equal(releasedWorker.status, 0, 'the pinned pre-daylight-fix worker remains available');
  assert.notEqual(serviceWorkerSource(), releasedWorker.stdout,
    'installed browsers must see changed worker bytes before they can deliver the continuous-daylight correction');
  const origin = "https://scanner.example";
  const handlers = {}, records = new Map(), networkRequests = [];
  const key = request => new URL(typeof request === "string" ? request : request.url, origin).href;
  const caches = {
    async open(name) {
      if (!records.has(name)) records.set(name, new Map());
      const entries = records.get(name);
      return {
        async addAll(requests) {
          for (const request of requests) {
            const url = new URL(key(request));
            const file = path.resolve(__dirname, url.pathname === "/" ? "index.html" : "." + url.pathname);
            assert.ok(file.startsWith(`${__dirname}${path.sep}`), "installation must stay inside the isolated shell");
            entries.set(url.href, new Response(fs.readFileSync(file)));
          }
        },
        async put(request, response) { entries.set(key(request), response.clone()); },
      };
    },
    async match(request) {
      for (const entries of records.values()) {
        const response = entries.get(key(request));
        if (response) return response.clone();
      }
    },
  };
  class ShellRequest extends Request {
    constructor(input, options) { super(key(input), options); }
  }
  vm.runInNewContext(serviceWorkerSource(), {
    caches, URL, Request: ShellRequest,
    fetch(request) {
      networkRequests.push(key(request));
      return Promise.reject(new Error(`Offline network request: ${key(request)}`));
    },
    self: {
      location: { origin },
      addEventListener(type, handler) { handlers[type] = handler; },
      skipWaiting() { return Promise.resolve(); },
      clients: { claim() { return Promise.resolve(); } },
    },
  }, { filename: "sw.js" });
  const installation = [];
  handlers.install({ waitUntil(promise) { installation.push(promise); } });
  await Promise.all(installation);

  const scripts = [...html.matchAll(/<script\b[^>]*\bsrc=["']([^"']+)["']/gi)]
    .map(match => new URL(match[1], origin + "/"))
    .filter(url => url.origin === origin);
  assert.ok(scripts.length > 0, "the fixture must use the production page's local scripts");
  for (const url of scripts) {
    let pending;
    handlers.fetch({ request: new Request(url), respondWith(promise) { pending = promise; } });
    assert.ok(pending, `the installed worker must handle ${url.pathname}`);
    await assert.doesNotReject(pending, `fresh installation must deliver ${url.pathname} offline`);
    const response = await pending;
    assert.ok(response?.ok, `offline delivery must succeed for ${url.pathname}`);
    assert.deepEqual(Buffer.from(await response.arrayBuffer()), fs.readFileSync(path.join(__dirname, url.pathname)),
      `offline delivery must retain the exact production bytes for ${url.pathname}`);
  }
  assert.deepEqual(networkRequests, [], "fresh installation must not depend on a prior online script fetch");
  const cachedSolar = vm.createContext({ Math });
  for (const file of ['landscape-config.js', 'vendor/astronomy.min.js', 'stars.js', 'landscape-core.js']) {
    let pending;
    handlers.fetch({ request: new Request(new URL(file, origin)), respondWith(promise) { pending = promise; } });
    vm.runInContext(await (await pending).text(), cachedSolar, { filename: 'offline/' + file });
  }
  const sky = vm.runInContext("LivingSky.skyAt(new Date('2026-06-21T00:28:09.928Z'), { latitude: 65.8, longitude: 18.96, timezone: 'Europe/Oslo' })", cachedSolar);
  assert.equal(sky.period, 'day', 'the actual offline-delivered solar consumer retains the continuous-daylight fix');
  assert.equal(cachedSolar.LivingSky.fireworksAllowed(sky), false, 'offline daylight excludes shows too');
});

function slice(src, startMarker, endMarker) {
  const s = src.indexOf(startMarker);
  const e = src.indexOf(endMarker);
  if (s === -1 || e === -1 || e < s) throw new Error(`markers not found: ${startMarker} .. ${endMarker}`);
  return src.slice(s + startMarker.length, e);
}
const engineSrc = slice(html, "/*ENGINE-START*/", "/*ENGINE-END*/");

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const SEED_SNIPPET = (seed) => `
Math.random = (function(seed){
  let a = seed >>> 0;
  return function(){
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
})(${seed});
`;

function loadEngine(seed) {
  const sandbox = {};
  vm.createContext(sandbox);
  // Seed FIRST, inside the context — vm contexts don't expose their built-in
  // Math as a settable property on the outer sandbox object, so reassigning
  // Math.random has to happen as code run *in* the context, not from outside.
  if (seed !== undefined) vm.runInContext(SEED_SNIPPET(seed), sandbox);
  vm.runInContext(engineSrc, sandbox, { filename: "index.html#engine" });
  return sandbox;
}
// `const`/`let` at top level (SIGMA_FLOOR, BETA, TAU, ...) live in the script's
// lexical scope, not as properties of the sandbox object — unlike `function`
// declarations, which do attach. Read them by evaluating the bare name inside
// the same context instead of via the returned object.
function readConst(sandbox, name) {
  return vm.runInContext(name, sandbox);
}

/* =====================================================================
   Harness for the FULL app script (state, decide/*, addTask, deleteTask,
   parseTaskList, the new queue-gate, etc.) — the classic (non-module)
   <script> block, identified by its "use strict" opener so it doesn't
   depend on script ordering in the file.
   ===================================================================== */
function extractAppScript(src) {
  const m = src.match(/<script>\s*"use strict";([\s\S]*?)<\/script>/);
  if (!m) throw new Error("could not find the main app <script> block");
  return '"use strict";' + m[1];
}
const appSrc = extractAppScript(html);

function makeFakeElement() {
  const el = {
    innerHTML: "", textContent: "", value: "", hidden: false, scrollTop: 0, children: [],
    dataset: {}, style: {},
    classList: {
      _set: new Set(),
      toggle(cls, force) {
        if (force === undefined) { this._set.has(cls) ? this._set.delete(cls) : this._set.add(cls); }
        else if (force) { this._set.add(cls); } else { this._set.delete(cls); }
      },
      add(cls) { this._set.add(cls); },
      remove(cls) { this._set.delete(cls); },
      contains(cls) { return this._set.has(cls); },
    },
    addEventListener() {}, removeEventListener() {},
    focus() {}, select() {}, click() {},
    querySelector() { return null; }, querySelectorAll() { return []; },
    // Attributes are really stored now (they used to be no-op stubs) so that
    // <html data-theme="..."> can be asserted on. getAttribute still returns
    // null for anything never set, which is what the old stub always did.
    _attrs: new Map(),
    getAttribute(k) { return this._attrs.has(k) ? this._attrs.get(k) : null; },
    setAttribute(k, v) { this._attrs.set(k, String(v)); },
    removeAttribute(k) { this._attrs.delete(k); },
    hasAttribute(k) { return this._attrs.has(k); },
    appendChild(child) { this.children.push(child); }, append(child) { this.children.push(child); }, scrollIntoView() {},
  };
  return el;
}

function makeDomShim({ prefersDark = false, sharedStorage = null } = {}) {
  const elements = new Map();
  const winListeners = {};
  const documentListeners = {};
  const localStorageMap = new Map();

  const documentElement = makeFakeElement();

  const document = {
    getElementById(id) {
      if (!elements.has(id)) elements.set(id, makeFakeElement());
      return elements.get(id);
    },
    querySelector() { return null; },   // "no modal open" by default
    querySelectorAll() { return []; },
    addEventListener(evt, fn) { (documentListeners[evt] ||= []).push(fn); },
    removeEventListener() {},
    dispatchEvent(evt) {
      for (const fn of (documentListeners[evt.type] || [])) fn(evt);
      return true;
    },
    createElement() { return makeFakeElement(); },
    body: { appendChild() {} },
    documentElement,
  };
  const localStorage = sharedStorage || {
    getItem(k) { return localStorageMap.has(k) ? localStorageMap.get(k) : null; },
    setItem(k, v) { localStorageMap.set(k, String(v)); },
    removeItem(k) { localStorageMap.delete(k); },
  };
  // A minimal MediaQueryList good enough for prefers-color-scheme. `setDark`
  // flips the OS preference and notifies listeners the way a real browser does
  // when you change the system appearance while the page is open.
  const mqlListeners = [];
  const mql = {
    media: "(prefers-color-scheme: dark)",
    matches: prefersDark,
    addEventListener(evt, fn) { if (evt === "change") mqlListeners.push(fn); },
    removeEventListener(evt, fn) {
      const i = mqlListeners.indexOf(fn);
      if (i >= 0) mqlListeners.splice(i, 1);
    },
  };
  function setDark(v) {
    mql.matches = !!v;
    for (const fn of [...mqlListeners]) fn({ matches: mql.matches, media: mql.media });
  }

  const window = {
    addEventListener(evt, fn) { (winListeners[evt] ||= []).push(fn); },
    removeEventListener() {},
    dispatchEvent(evt) {
      for (const fn of (winListeners[evt.type] || [])) fn(evt);
      return true;
    },
    matchMedia(q) {
      // Only the color-scheme query is modelled; anything else reports no match.
      if (String(q).includes("prefers-color-scheme: dark")) return mql;
      return { media: String(q), matches: false, addEventListener() {}, removeEventListener() {} };
    },
    localStorage,
    CloudSync: undefined,
  };
  window.window = window;
  return { document, window, localStorage, elements, winListeners, documentElement, setDark, mqlListeners };
}

const flush = () => new Promise((r) => setTimeout(r, 0));

async function loadApp({ appSource=appSrc, artifacts=null, seed, cloudSyncFactory, prefersDark = false, noMatchMedia = false, seedStorage, sharedStorage, hostStorage, hostStorageDelayMs = 0, beforeStateReady, navigatorProvider, cryptoProvider = webcrypto, indexedDBProvider, deviceDbName, deviceOpenTimeoutMs, withSceneModules = false, sceneModulesAfterDomReady = false, locationHref, fetchProvider } = {}) {
  const shim = makeDomShim({ prefersDark, sharedStorage });
  const ownedTimers=new Set();let disposed=false,sandbox;
  const fixture={async dispose(){
    if(disposed)return;
    disposed=true;sandbox?.suspendCloudSync?.();
    for(const timer of ownedTimers)clearTimeout(timer);
    ownedTimers.clear();await shim.window.ScannerDeviceStore?.close?.();
  }};
  appFixtureScope.getStore()?.add(fixture); // before startup, including failed boots
  const schedule=(fn,ms,...args)=>{
    // A late in-flight continuation cannot revive a disposed fixture.
    const timer=setTimeout(()=>{ownedTimers.delete(timer);if(!disposed)fn(...args);},ms);
    if(disposed)clearTimeout(timer);else ownedTimers.add(timer);
    timer.unref?.();return timer;
  };
  const cancel=timer=>{ownedTimers.delete(timer);clearTimeout(timer);};
  if(locationHref)shim.window.location=new URL(locationHref);
  if(fetchProvider){shim.window.fetch=fetchProvider;shim.window.AbortController=AbortController;}
  if (noMatchMedia) delete shim.window.matchMedia;   // old browser / bare JS host
  if (seedStorage) for (const [k, v] of Object.entries(seedStorage)) shim.localStorage.setItem(k, v);
  /* The OTHER persistence backend. loadState() prefers window.storage (the
     artifact host's async key-value store) and only falls back to
     localStorage — `useLocal` — when there isn't one. Every existing test
     runs the localStorage path; pass hostStorage to run the other. */
  if (hostStorage) {
    const map = new Map(Object.entries(hostStorage));
    shim.window.storage = {
      _map: map,
      async get(k) {
        if (hostStorageDelayMs) await new Promise((resolve) => setTimeout(resolve, hostStorageDelayMs));
        return map.has(k) ? { value: map.get(k) } : null;
      },
      async set(k, v) { map.set(k, String(v)); },
    };
  }
  if (cloudSyncFactory) shim.window.CloudSync = cloudSyncFactory(shim.window);
  if (deviceDbName) shim.window.CHAIN_STORAGE_DB_NAME = deviceDbName;
  if (deviceOpenTimeoutMs) shim.window.CHAIN_STORAGE_OPEN_TIMEOUT_MS = deviceOpenTimeoutMs;
  if (indexedDBProvider) shim.window.indexedDB = indexedDBProvider;
  sandbox = {
    navigator:navigatorProvider,
    window: shim.window,
    document: shim.document,
    localStorage: shim.localStorage,
    URL,
    AbortController,
    fetch:fetchProvider,
    console,
    JSON,
    crypto:cryptoProvider,
    indexedDB:indexedDBProvider,
    TextEncoder,
    TextDecoder,
    Uint8Array,
    structuredClone,
    AbortController,
    performance,
    // NOTE: deliberately NOT injecting the outer process's `Date` here — it's
    // passed by reference, so overriding Date.now on it (for time-travel
    // tests) would leak into the whole Node process. Leave Date unset and the
    // vm context auto-provisions its own separate, safely-overridable Date;
    // see setFakeTime() below, which overrides it via in-context code only.
    CustomEvent: class CustomEvent { constructor(type, opts) { this.type = type; Object.assign(this, opts || {}); } },
    setTimeout: schedule,
    clearTimeout: cancel,
    requestAnimationFrame: (fn) => schedule(fn, 0),
    confirm: () => true,
    alert: () => {},
    prompt: () => null,
  };
  vm.createContext(sandbox);
  vm.runInContext(lzStringSrc, sandbox, { filename: "vendor/lz-string-1.5.0.min.js" });
  if(indexedDBProvider){
    vm.runInContext(artifacts?.storage||fs.readFileSync(path.join(__dirname,"device-store-v2.js"),"utf8"),sandbox,{filename:"device-store-v2.js"});
    vm.runInContext(artifacts?.cloud||fs.readFileSync(path.join(__dirname,"cloud-store-v2.js"),"utf8"),sandbox,{filename:"cloud-store-v2.js"});
    shim.window.ChainStorageV2=sandbox.ChainStorageV2;
    shim.window.ChainCloudV2=sandbox.ChainCloudV2;
  }
  if (seed !== undefined) vm.runInContext(SEED_SNIPPET(seed), sandbox);
  const installSceneModules = () => {
    vm.runInContext(fs.readFileSync(path.join(__dirname, "location.js"), "utf8"), sandbox, { filename: "location.js" });
    const timeKey = "fvp:chain-scanner:scene-time", seasonKey = "fvp:chain-scanner:scene-season";
    sandbox.LivingSky = {
      readSceneTime: storage => storage.getItem(timeKey),
      readSceneSeason: storage => storage.getItem(seasonKey),
    };
    return () => { shim.window.applySyncedSceneTime = (time, season) => {
      if (time === null) shim.localStorage.removeItem(timeKey);
      else shim.localStorage.setItem(timeKey, time);
      if (season === null) shim.localStorage.removeItem(seasonKey);
      else shim.localStorage.setItem(seasonKey, season);
    }; };
  };
  if (withSceneModules && !sceneModulesAfterDomReady) installSceneModules()();
  if (sceneModulesAfterDomReady) shim.document.readyState = "loading";
  shim.document.currentScript={textContent:appSource,src:""};
  vm.runInContext(appSource, sandbox, { filename: "index.html#app" });
  shim.document.currentScript=null;
  beforeStateReady?.(sandbox, shim);
  if(/<script\b[^>]*\bsrc=["']app-release\.js["']/i.test(html))
    vm.runInContext(fs.readFileSync(path.join(__dirname,"app-release.js"),"utf8"),sandbox,{filename:"app-release.js"});
  if (sceneModulesAfterDomReady) {
    await flush(); // the inline boot script can resume before deferred modules execute
    const installTimeHook=installSceneModules();
    shim.document.readyState = "interactive";
    shim.document.dispatchEvent({ type: "DOMContentLoaded" });
    await flush(); // landscape.js also awaits its local spawn-rates file
    installTimeHook();
    shim.document.dispatchEvent({ type: "landscape-scene-time-ready" });
  }
  // `state` is a top-level `let`, reassigned wholesale by undo()/cloudPull() —
  // expose it as a live getter (re-reading the binding each time) rather than
  // a one-time snapshot, so it never goes stale after such a reassignment.
  Object.defineProperty(sandbox, "state", {
    get() { return vm.runInContext("state", sandbox); },
    configurable: true,
  });
  // `esc` is a top-level `const` arrow fn (not `function esc(){}`), so — like
  // SIGMA_FLOOR and state — it never attaches to the sandbox object on its
  // own. It's never reassigned though, so a one-time copy is fine here.
  vm.runInContext("this.esc = esc;", sandbox);
  await flush(); // let the boot IIFE's `await loadState()` resolve before returning
  if(indexedDBProvider){
    // Hashing and IndexedDB completion are not bounded by an event-loop count.
    // Await readiness with an explicit deadline so slowness cannot masquerade
    // as an unrelated task-action failure against null state.
    const deadline=Date.now()+5000;
    while(vm.runInContext("state",sandbox)===null && Date.now()<deadline) await flush();
    assert.notEqual(vm.runInContext("state",sandbox),null,"App durable startup did not finish within 5 seconds");
  }
  return { ctx: sandbox, shim, dispose:fixture.dispose };
}

test("app harness: disposal cancels its real wake and late timers while another fixture still runs",async()=>{
 const closed=await loadApp(),neighbor=await loadApp();let stale=false,late=false;
 const wake=vm.runInContext("scanWakeTimer",closed.ctx),otherWake=vm.runInContext("scanWakeTimer",neighbor.ctx);
 assert.ok(wake&&!wake._destroyed,"the actual scanner owns a pending long-lived wake");
 closed.ctx.setTimeout(()=>{stale=true;},0);
 await closed.dispose();assert.equal(wake._destroyed,true);
 closed.ctx.setTimeout(()=>{late=true;},0);
 await new Promise(resolve=>neighbor.ctx.setTimeout(resolve,0).ref());
 assert.equal(stale,false,"closed app callbacks never run after their owning test");
 assert.equal(late,false,"late continuations cannot revive a closed app");
 assert.equal(otherWake._destroyed,false,"another live app retains its own wake");
});

// Overrides Date.now() *inside one vm context only*, via in-context code —
// never touches the outer process's real Date, so it can't leak across tests.
function setFakeTime(sandbox, ts) {
  vm.runInContext(`Date.now = () => ${ts};`, sandbox);
}
function realNow(sandbox) {
  return vm.runInContext("Date.now()", sandbox);
}

test("app harness: boots cleanly with an empty state", async () => {
  const { ctx } = await loadApp();
  assert.ok(ctx.state, "state should be initialized after boot");
  assert.equal(ctx.state.tasks.length, 0);
  assert.equal(ctx.state.chain.length, 0);
  assert.equal(ctx.state.mode, "scan");
});

test('RISK apology notice: an eligible Beta login shows the exact original apology',async()=>{
 const at=Date.parse('2026-10-20T12:00:00.000Z'),startsAt=at-60*60*1000,requests=[];
 assert.equal(createHash('sha256').update(ORIGINAL_APOLOGY,'utf8').digest('hex'),'5ddea3c755f9477e33908f16b94867a0ee9e4004e46ab169131cd814cf7188b2');
 const envelope=channelReleaseEnvelope('beta',startsAt,startsAt);
 const app=await loadAppAtTime(at,{
  locationHref:'https://chain-scanner.web.app/',
  fetchProvider:async(url,options)=>{
   requests.push({url:String(url),options});
   return {ok:true,redirected:false,type:'basic',url:String(url),json:async()=>envelope};
  },
  cloudSyncFactory:()=>({ready:false,user:null,status:'idle',configured:true,recoveryIdentity:()=> 'beta-uid'}),
  beforeStateReady:(_ctx,shim)=>{shim.document.getElementById('appChangelogCurrent').innerHTML=html.match(/<template id="appChangelogCurrent">([\s\S]*?)<\/template>/)[1];},
 });
 app.ctx.closeModal();
 const cloud=app.ctx.window.CloudSync;cloud.ready=true;cloud.user='beta-account';
 app.ctx.window.dispatchEvent(new app.ctx.CustomEvent('cloudsync'));
 const modal=app.shim.document.getElementById('modalRoot').innerHTML;
 const expectedHtml=ORIGINAL_APOLOGY.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\n\n/g,'<br><br>');
 assert.ok(modal.includes(expectedHtml),'the real signed-in app consumer should show the original copy inside its automatic Beta window');
 assert.equal(requests.length,1,'the page obtains channel identity from the public release envelope');
 assert.equal(new URL(requests[0].url).pathname,'/channel-release.json');
 assert.equal(requests[0].options.credentials,'omit');
 assert.equal(requests[0].options.cache,'no-store');
 assert.equal(requests[0].options.redirect,'error');
 assert.equal(app.ctx.window.ChainRelease?.current?.channel,'beta');
});

function publishedBetaContinuation(){
 const startsAt='2026-10-20T19:42:33.722Z';
 return {schemaVersion:1,channel:'beta',origin:'https://chain-scanner.web.app',basePath:'/',noticeId:APOLOGY_NOTICE_ID,
  originalProduct:{sourceRevision:'b50ac1694502090a51503fdaa79d97d19d13d43e',tree:'d0a89f3232179b5fe6368744b9a69a82b533f547',appFingerprint:'cc008c890dc3f5de3ce1e5fb35c8a3dede880d3aec5d6881e4c563fce722ec48'},
  originalDeployedAt:startsAt,originalStartsAt:startsAt,
  evidence:{artifactSha256:'c3f68dab62ed156e413e88d78c0901c761f9f013edb97528a5fadb8e29ae880e',publicationSha256:'1'.repeat(64),publicVerificationSha256:'2'.repeat(64)}};
}

test('RISK apology release identity: a later Beta product retains the published notice window',async()=>{
 const startsAt='2026-10-20T19:42:33.722Z',deployedAt='2026-10-22T12:00:00.000Z',at=Date.parse('2026-10-23T12:00:00.000Z');
 const envelope=channelReleaseEnvelope('beta',startsAt,deployedAt),continuation=publishedBetaContinuation();
 envelope.notices[APOLOGY_NOTICE_ID].continuation=continuation;
 const app=await loadAppAtTime(at,{
  locationHref:'https://chain-scanner.web.app/',
  fetchProvider:async url=>({ok:true,redirected:false,type:'basic',url:String(url),json:async()=>envelope}),
  cloudSyncFactory:()=>({ready:false,user:null,status:'idle',configured:true,recoveryIdentity:()=> 'continued-beta-uid'}),
  beforeStateReady:(_ctx,shim)=>{shim.document.getElementById('appChangelogCurrent').innerHTML=html.match(/<template id="appChangelogCurrent">([\s\S]*?)<\/template>/)[1];},
 });
 assert.equal(app.ctx.window.ChainRelease?.status,'verified','the actual metadata consumer accepts explicit original-publication provenance for a later product');
 const release=app.ctx.window.ChainRelease.current;
 assert.equal(release.deployedAt,deployedAt,'the product keeps its own later publication time');
 assert.equal(release.notices[APOLOGY_NOTICE_ID].startsAt,startsAt,'the campaign keeps its original start');
 assert.equal(JSON.stringify(release.notices[APOLOGY_NOTICE_ID].continuation),JSON.stringify(continuation),'the validated provenance remains inspectable');
 assert.equal(Object.isFrozen(release.notices[APOLOGY_NOTICE_ID].continuation.evidence),true,'nested public provenance is immutable');
 const before=JSON.stringify(app.ctx.state);
 app.ctx.closeModal();const cloud=app.ctx.window.CloudSync;cloud.ready=true;cloud.user='continued@example.invalid';
 app.ctx.window.dispatchEvent(new app.ctx.CustomEvent('cloudsync'));
 assert.match(app.shim.document.getElementById('modalRoot').innerHTML,/data-apology-notice="sync-stability-2026-10"/,'the signed-in consumer remains eligible within the original window');
 assert.equal(JSON.stringify(app.ctx.state),before,'release metadata and display do not alter the board');
});

test('RISK apology release identity: malformed continuation fails closed at the network consumer',async()=>{
 const startsAt='2026-10-20T19:42:33.722Z',deployedAt='2026-10-22T12:00:00.000Z',at=Date.parse('2026-10-23T12:00:00.000Z');
 const cases=[
  ['null',notice=>{notice.continuation=null;}],
  ['array',notice=>{notice.continuation=[];}],
  ['unknown field',notice=>{notice.continuation.path='/private/evidence';}],
  ['wrong schema',notice=>{notice.continuation.schemaVersion=2;}],
  ['wrong channel',notice=>{notice.continuation.channel='stable';}],
  ['wrong origin',notice=>{notice.continuation.origin='https://unverified.example';}],
  ['wrong path',notice=>{notice.continuation.basePath='/funsidething/';}],
  ['wrong notice',notice=>{notice.continuation.noticeId='another-notice';}],
  ['bad product',notice=>{notice.continuation.originalProduct.tree='bad';}],
  ['array original source',notice=>{notice.continuation.originalProduct.sourceRevision=[notice.continuation.originalProduct.sourceRevision];}],
  ['array original tree',notice=>{notice.continuation.originalProduct.tree=[notice.continuation.originalProduct.tree];}],
  ['array original fingerprint',notice=>{notice.continuation.originalProduct.appFingerprint=[notice.continuation.originalProduct.appFingerprint];}],
  ['array current source',(_notice,envelope)=>{envelope.product.sourceRevision=[envelope.product.sourceRevision];}],
  ['array current tree',(_notice,envelope)=>{envelope.product.tree=[envelope.product.tree];}],
  ['extra product field',notice=>{notice.continuation.originalProduct.extra=true;}],
  ['missing evidence',notice=>{delete notice.continuation.evidence.publicationSha256;}],
  ['bad evidence hash',notice=>{notice.continuation.evidence.artifactSha256='bad';}],
  ['extra evidence field',notice=>{notice.continuation.evidence.path='/private';}],
  ['noncanonical time',notice=>{notice.continuation.originalDeployedAt='2026-10-20T19:42:33Z';}],
  ['original starts before publication',notice=>{notice.continuation.originalDeployedAt='2026-10-21T00:00:00.000Z';}],
  ['original publication after current',notice=>{notice.startsAt='2026-10-24T12:00:00.000Z';notice.continuation.originalStartsAt=notice.startsAt;notice.continuation.originalDeployedAt=notice.startsAt;}],
  ['renewed start',notice=>{notice.startsAt=deployedAt;}],
  ['malformed proof with otherwise valid legacy order',notice=>{notice.startsAt=deployedAt;notice.continuation=null;}],
 ];
 for(const [label,mutate] of cases){
  const envelope=channelReleaseEnvelope('beta',startsAt,deployedAt);envelope.notices[APOLOGY_NOTICE_ID].continuation=publishedBetaContinuation();mutate(envelope.notices[APOLOGY_NOTICE_ID],envelope);
  const app=await loadAppAtTime(at,{locationHref:'https://chain-scanner.web.app/',
   fetchProvider:async url=>({ok:true,redirected:false,type:'basic',url:String(url),json:async()=>envelope}),
   cloudSyncFactory:()=>({ready:false,user:null,status:'idle',configured:true,recoveryIdentity:()=> 'invalid-continuation-uid'}),
   beforeStateReady:(_ctx,shim)=>{shim.document.getElementById('appChangelogCurrent').innerHTML=html.match(/<template id="appChangelogCurrent">([\s\S]*?)<\/template>/)[1];},
  });
  assert.equal(app.ctx.window.ChainRelease?.status,'unavailable',label);
  const before=JSON.stringify(app.ctx.state);app.ctx.closeModal();const cloud=app.ctx.window.CloudSync;cloud.ready=true;cloud.user='invalid@example.invalid';app.ctx.window.dispatchEvent(new app.ctx.CustomEvent('cloudsync'));
  assert.doesNotMatch(app.shim.document.getElementById('modalRoot').innerHTML,/data-apology-notice=/,label+': no automatic notice');
  assert.equal(JSON.stringify(app.ctx.state),before,label+': board retained');
  assert.equal(app.shim.localStorage.getItem('fvp:chain-scanner:release-notice:v1:sync-stability-2026-10:beta:invalid-continuation-uid'),null,label+': no notice marker');
 }
});

test('RISK apology notice: continuation preserves expiry dismissal manual reopen and separate Stable',async()=>{
 const startsAt=Date.parse('2026-10-20T19:42:33.722Z'),day=86400000,values=new Map();
 const storage={getItem:key=>values.get(key)??null,setItem:(key,value)=>values.set(key,String(value)),removeItem:key=>values.delete(key)};
 const setup=async(channel,at,uid)=>{
  const envelope=channelReleaseEnvelope(channel,channel==='beta'?startsAt:at-day/24,channel==='beta'?startsAt+day:at-day/24);
  if(channel==='beta')envelope.notices[APOLOGY_NOTICE_ID].continuation=publishedBetaContinuation();
  const app=await loadAppAtTime(at,{locationHref:channel==='beta'?'https://chain-scanner.web.app/':'https://emerald-pham.github.io/funsidething/',sharedStorage:storage,
   fetchProvider:async url=>({ok:true,redirected:false,type:'basic',url:String(url),json:async()=>envelope}),
   cloudSyncFactory:()=>({ready:false,user:null,status:'idle',configured:true,recoveryIdentity:()=>uid}),
   beforeStateReady:(_ctx,shim)=>{shim.document.getElementById('appChangelogCurrent').innerHTML=html.match(/<template id="appChangelogCurrent">([\s\S]*?)<\/template>/)[1];},
  });
  assert.equal(app.ctx.window.ChainRelease.status,'verified');app.ctx.closeModal();const cloud=app.ctx.window.CloudSync;cloud.ready=true;cloud.user=uid+'@example.invalid';app.ctx.window.dispatchEvent(new app.ctx.CustomEvent('cloudsync'));return app;
 };
 const first=await setup('beta',startsAt+2*day,'continued-dismissed');
 assert.match(first.shim.document.getElementById('modalRoot').innerHTML,/data-apology-notice=/);first.ctx.closeModal();
 const key='fvp:chain-scanner:release-notice:v1:sync-stability-2026-10:beta:continued-dismissed';assert.equal(storage.getItem(key),'dismissed');
 const returning=await setup('beta',startsAt+3*day,'continued-dismissed');
 assert.doesNotMatch(returning.shim.document.getElementById('modalRoot').innerHTML,/data-apology-notice=/,'a later product does not clear the account dismissal');
 const expired=await setup('beta',startsAt+7*day,'continued-unshown');
 assert.doesNotMatch(expired.shim.document.getElementById('modalRoot').innerHTML,/data-apology-notice=/,'the original expiry applies even though this product is newer');
 assert.equal(storage.getItem(key.replace('continued-dismissed','continued-unshown')),null,'expiry does not consume a new marker');
 expired.ctx.openHelp();const before=[...values];expired.ctx.onAction('reopen-apology',{});
 assert.ok(expired.shim.document.getElementById('modalRoot').innerHTML.includes(ORIGINAL_APOLOGY.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\n\n/g,'<br><br>')),'manual reopen retains the exact original copy after expiry');
 assert.deepEqual([...values],before,'manual reopen does not renew the window or change saved facts');
 const stable=await setup('stable',startsAt+8*day,'continued-dismissed');
 assert.match(stable.shim.document.getElementById('modalRoot').innerHTML,/data-apology-notice=/,'Stable retains a separate fresh ordinary window for that account');
});

