/* =====================================================================
   REGRESSION: A STALE DEVICE MUST NOT OVERWRITE A NEWER CLOUD STATE

   The incident: a browser holding weeks-old localStorage was opened and
   its stale chain replaced a chain that had been built up in the cloud
   over a full day of work on another device. Three separate defects in
   the sync glue each allow that on their own.

   1. CS.pull() returned null both for "the document does not exist" and
      for "the read threw", and cloudPull() read null as an empty cloud
      and seeded it from this device. One flaky first request on a stale
      tab was enough to overwrite a perfectly good remote document.

   2. Pushes were gated only on "is auth ready", never on "has this
      session actually seen the cloud yet". cloudPushNow() (dotting,
      deleting) fires with no comparison at all, so an edit made in the
      seconds before the first pull landed wrote stale content straight
      over the remote.

   3. save() stamps state.updatedAt = Date.now() on every local write.
      On a device that had not reconciled yet, that put a fresh timestamp
      on weeks-old content, which then won the last-write-wins comparison
      in cloudPull() — so the stale side was declared "ahead" and pushed
      deliberately, not just by racing.

   The fix has to close all three: a failed read is not an empty cloud,
   nothing is written before the session reconciles once, and the first
   reconcile judges this device by the timestamp it LOADED with rather
   than one a local edit has since re-stamped.
   ===================================================================== */

const SYNC_STORE_KEY = "fvp:chain-scanner:v1";
const LOCAL_HEAD_KEY = "fvp:chain-scanner:protected:v1";
const LOCAL_BACKUPS_KEY = "fvp:chain-scanner:daily-backups:v1";
const DEVICE_AUTHORITY_KEY = "fvp:chain-scanner:device-store-v2";
const HOUR = 3600000;

function sharedScannerStorage(initial = {}) {
  const values = new Map(Object.entries(initial));
  return {
    getItem: key => values.has(key) ? values.get(key) : null,
    setItem: (key, value) => values.set(key, String(value)),
    removeItem: key => values.delete(key),
  };
}

test('STALE TAB: a September 2 tab cannot replace a September 23 browser save or cloud revision', async () => {
  const september2 = Date.parse('2026-09-02T12:00:00Z');
  const september23 = Date.parse('2026-09-23T12:00:00Z');
  const storage = sharedScannerStorage({ [SYNC_STORE_KEY]: JSON.stringify(staleState(september2)) });
  const oldTab = await loadApp({ sharedStorage: storage });
  const currentTab = await loadApp({ sharedStorage: storage });
  setFakeTime(currentTab.ctx, september23);
  currentTab.ctx.addTask('September 23 history');
  assert.equal(await currentTab.ctx.persist(), true);
  const currentBytes = storage.getItem(SYNC_STORE_KEY);
  setFakeTime(oldTab.ctx, september23 + 1000);
  oldTab.ctx.addTask('Stale tab edit');
  await oldTab.ctx.persist();
  assert.notEqual(storage.getItem(SYNC_STORE_KEY), currentBytes, 'both edits are retained in a new save');
  assert.ok(JSON.parse(storage.getItem(SYNC_STORE_KEY)).tasks.some(task => task.title === 'September 23 history'), 'current history stays durable');
  assert.ok(JSON.parse(storage.getItem(SYNC_STORE_KEY)).tasks.some(task => task.title === 'Stale tab edit'), 'unrecorded stale-tab task is merged');
  assert.ok(oldTab.ctx.state.tasks.some(task => task.title === 'September 23 history'), 'stale tab reloads current board');
  assert.ok(oldTab.ctx.readLocalBackups().some(entry => entry.payload.includes('Stale tab edit')), 'rejected draft remains restorable');
});

test('CLOUD MERGE: a higher revision without deletion evidence retains older unique tasks', async () => {
  const local = syncState({ tasks: [syncTask('september23', 'September 23 no-history task')], syncRev: 4 });
  const remote = syncState({ tasks: [syncTask('september2', 'Old tab task')] });
  const h = makeSyncHarness({ remote, rev: 5 });
  const { ctx } = await loadApp({ seedStorage: { [SYNC_STORE_KEY]: JSON.stringify(local) }, cloudSyncFactory: h.factory });
  await ctx.cloudPull(); await syncSettle(PAST_DEBOUNCE);
  assert.deepEqual(new Set(Array.from(ctx.state.tasks, task => task.id)), new Set(['september23', 'september2']));
  assert.deepEqual(new Set(h.remoteState().tasks.map(task => task.id)), new Set(['september23', 'september2']));
});

test('CLOUD MERGE: explicit deletion evidence prevents resurrection on a stale device', async () => {
  const local = syncState({ tasks: [syncTask('keep', 'Keep'), syncTask('remove', 'Remove')], syncRev: 4 });
  const remote = syncState({ tasks: [syncTask('keep', 'Keep')], deletedTaskIds: { remove: true } });
  const h = makeSyncHarness({ remote, rev: 5 });
  const { ctx } = await loadApp({ seedStorage: { [SYNC_STORE_KEY]: JSON.stringify(local) }, cloudSyncFactory: h.factory });
  await ctx.cloudPull();
  assert.deepEqual(Array.from(ctx.state.tasks, task => task.id), ['keep']);
  ctx.deleteTask('keep');
  assert.equal(ctx.state.deletedTaskIds.keep, true);
});

test('CLOUD REVISION: a server date alone cannot replace unsynced work at the same revision', async () => {
  const local = syncState({ tasks: [syncTask('shared', 'Local edit')], syncRev: 4, lastCloudServerAt: 1000 });
  const remote = syncState({ tasks: [syncTask('shared', 'Prior cloud value')] });
  const h = makeSyncHarness({ remote, rev: 4 });
  h.doc.serverUpdatedAt = { toMillis: () => 2000 };
  const { ctx } = await loadApp({ seedStorage: { [SYNC_STORE_KEY]: JSON.stringify(local) }, cloudSyncFactory: h.factory });
  await ctx.cloudPull();
  assert.equal(ctx.state.tasks[0].title, 'Local edit', 'same revision means the local edit may still need to be pushed');
  assert.ok(!JSON.parse(ctx.cloudPayload()).lastCloudServerAt, 'server read watermark remains device local');
});

test('CLOUD TIME: equal server milliseconds fall back to revision so a newer write is adopted', async () => {
  const local=syncState({tasks:[syncTask('local','Local')],syncRev:4,lastCloudServerAt:1000});
  const remote=syncState({tasks:[syncTask('remote','Remote')]});
  const h=makeSyncHarness({remote,rev:5}); h.doc.serverUpdatedAt={toMillis:()=>1000};
  const {ctx}=await loadApp({seedStorage:{[SYNC_STORE_KEY]:JSON.stringify(local)},cloudSyncFactory:h.factory});
  await ctx.cloudPull();
  assert.ok(ctx.state.tasks.some(task=>task.id==='remote'));
});

test('CLOUD REVISION: a higher cloud revision wins even when its server clock reads earlier', async () => {
  const local=syncState({tasks:[syncTask('shared','Later local')],syncRev:4,lastCloudServerAt:2000});
  const remote=syncState({tasks:[syncTask('shared','Newer revision')]});
  const h=makeSyncHarness({remote,rev:5}); h.doc.serverUpdatedAt={toMillis:()=>1000};
  const {ctx}=await loadApp({seedStorage:{[SYNC_STORE_KEY]:JSON.stringify(local)},cloudSyncFactory:h.factory});
  await ctx.cloudPull(); await syncSettle(PAST_DEBOUNCE);
  assert.equal(ctx.state.tasks[0].title,'Newer revision');
  assert.equal(h.remoteState().tasks[0].title,'Newer revision');
  assert.equal(h.conflicts,0);
});

test('CLOUD TIME: Firestore writes request an authoritative server timestamp', () => {
  assert.match(html, /tx\.set\(root,next\)/);
  assert.match(html, /serverUpdatedAt:F\.serverTimestamp\(\)/,'the v2 manifest publication still uses Firestore server time');
  assert.match(html, /sealedAt:F\.serverTimestamp\(\)/,'generation visibility is also server-stamped');
});

test('CLOUD ACCOUNT: a transaction binds its document before auth can switch', () => {
  const push=html.slice(html.indexOf('CS.push = async'),html.indexOf('A.onAuthStateChanged'));
  assert.match(push,/const pushUser\s*=\s*auth\.currentUser/);
  assert.match(push,/const pushUid\s*=\s*pushUser\.uid/);
  assert.match(html,/const rootRef=uid=>F\.doc\(db,"users",uid\)/);
  assert.match(html,/publishGeneration\(uid,id,\{baseRev,updatedAt,hash,expectedHeader,stillCurrent,decisionCapability\}\)/);
  assert.match(html,/if\(stillCurrent&&!stillCurrent\(\)\)return \{cancelled:true\}/,'the manifest transaction rechecks identity after its reads');
  assert.match(push,/const stillCurrent=\(\)=>auth\.currentUser\?\.uid===pushUid&&operation===pushOperation&&recoveryStillCurrent\(\)/,'the shared named guard retains both captured identity and operation');
  assert.match(push,/generationStore\.push\(pushUid,[\s\S]*?stillCurrent\}\)/,'the exact captured guard reaches the publication adapter');
  assert.match(push,/if\(!stillCurrent\(\)\) return \{cancelled:true\}/,'a late result from an earlier account cannot change current cloud status');
});

async function loadCloudBackend({ serverData={rev:4}, serverExists=true, failures={}, timeoutMs=25, cryptoProvider=webcrypto }={}){
  const rootData=serverExists?{...serverData}:null;
  const h=await loadCloudBackendV2({rootData,failures,timeoutMs,cryptoProvider});
  return {...h,getStored:()=>({exists:h.docs.has('users/owner'),data:h.docs.get('users/owner')})};
}

