 for(const key of ['syncRev','syncAccount','lastCloudServerAt','syncDirty','protectedBackupIds']) delete remote[key];
 const pinned={id:'confirmed-adoption',day,at,kind:'before-cloud-adoption',payload:JSON.stringify(local)};
