  ctx.openSettings();const settings=shim.document.getElementById('modalRoot').innerHTML;
  const action=settings.match(/<button\b[^>]*data-act="([^"]*restore-backup[^"]*)"[^>]*>\s*Restore\s*<\/button>/);
