  const {ctx}=await loadApp();const a=ctx.addTask('A'),b=ctx.addTask('B');a.evergreen=evergreen;
  ctx.state.chain=route==='bench'?[b.id,a.id]:[b.id];ctx.state.candidateId=route==='candidate'?a.id:null;
