function loadStorageV2({indexedDB}={}){
 const file=path.join(__dirname,'device-store-v2.js');
 assert.ok(fs.existsSync(file),'the scalable local/cloud storage module must ship with the offline app');
 const sandbox=vm.createContext({console,crypto:webcrypto,TextEncoder,TextDecoder,Uint8Array,indexedDB,
  setTimeout,clearTimeout,structuredClone});
 sandbox.globalThis=sandbox;
 vm.runInContext(fs.readFileSync(file,'utf8'),sandbox,{filename:'device-store-v2.js'});
 assert.ok(sandbox.ChainStorageV2,'the storage module exposes its browser API');
 return sandbox.ChainStorageV2;
}

test('RISK DEVICE STORAGE V2: raw export snapshot preserves exact sources in one read-only capture',async t=>{
 const {IDBFactory}=await import('fake-indexeddb'),indexedDB=new IDBFactory(),dbName='chain-scanner-raw-export-'+Date.now()+'-'+Math.random();
 const transactionReads=[];let openCalls=0,abortNextSnapshot=false;
 const nativeOpen=indexedDB.open.bind(indexedDB);
 indexedDB.open=(...args)=>{
  openCalls++;
  const request=nativeOpen(...args);
  request.addEventListener('success',event=>{
   const db=event.target.result,nativeTransaction=db.transaction.bind(db);
   db.transaction=(...transactionArgs)=>{
    const tx=nativeTransaction(...transactionArgs),names=Array.from(tx.objectStoreNames);
    transactionReads.push({names,mode:tx.mode});
    if(abortNextSnapshot&&tx.mode==='readonly'&&names.length===4){
     abortNextSnapshot=false;let issued=0;
     const nativeObjectStore=tx.objectStore.bind(tx);
     tx.objectStore=name=>{
      const objectStore=nativeObjectStore(name);
      for(const method of ['getAllKeys','getAll']){
       const nativeRequest=objectStore[method].bind(objectStore);
       objectStore[method]=(...requestArgs)=>{
        const result=nativeRequest(...requestArgs);
        if(++issued===8)tx.abort();
        return result;
       };
      }
      return objectStore;
     };
    }
    return tx;
   };
  });
  return request;
 };
 const storageV2=loadStorageV2({indexedDB}),store=storageV2.createDeviceStore({indexedDB,crypto:webcrypto,dbName});
 await store.open();t.after(async()=>{await store.close();});
 const rawOpen=await new Promise((resolve,reject)=>{
  const request=indexedDB.open(dbName);
  request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);
 });
 t.after(()=>rawOpen.close());
 const expected={
  meta:{keys:['head','pending:owner@example.test'],values:[
   {hash:'corrupt-head-hash',schemaVersion:99,futureMeta:{raw:new Uint8Array([0,255,128])}},
   {account:'owner@example.test',generationId:'pending-opaque-190',payloadHash:'not-a-hash',futurePending:{keep:['exact',7]}},
  ]},
  snapshots:{keys:['snapshot-corrupt'],values:[{hash:'mismatch',payload:new Uint8Array([123,0,255]),futureSnapshot:'keep'}]},
  backups:{keys:['manual-corrupt'],values:['raw\u0000backup\uD800bytes']},
  opaque:{keys:['opaque-archive'],values:[{raw:new Uint8Array([0,255,13]),futureOpaque:{retain:true}}]},
 };
 const seed=rawOpen.transaction(['meta','snapshots','backups','opaque'],'readwrite');
 for(const [name,fixture] of Object.entries(expected)){
  const objectStore=seed.objectStore(name);
  for(let index=0;index<fixture.keys.length;index++)objectStore.put(fixture.values[index],fixture.keys[index]);
 }
 await new Promise((resolve,reject)=>{seed.oncomplete=resolve;seed.onerror=()=>reject(seed.error);seed.onabort=()=>reject(seed.error||new Error('fixture seed aborted'));});
 const unopened=storageV2.createDeviceStore({indexedDB,crypto:webcrypto,dbName:dbName+'-unopened'}),opensBeforeUnopenedCall=openCalls;
 assert.equal(typeof store.readRawExportSnapshot,'function','the existing open device-store exposes the additive raw export port');
 await assert.rejects(unopened.readRawExportSnapshot(),/not open/i,'the export port cannot open or create a database on its own');
 assert.equal(openCalls,opensBeforeUnopenedCall,'reading from a closed handle performs no IndexedDB open');

 transactionReads.length=0;
 const readsBeforeSnapshot=openCalls,snapshot=await store.readRawExportSnapshot();
 assert.equal(openCalls,readsBeforeSnapshot,'a snapshot reuses the already-open database handle');
 assert.deepEqual(transactionReads,[{names:['backups','meta','opaque','snapshots'],mode:'readonly'}],
  'one readonly transaction covers all existing app-owned stores');
 assert.deepEqual(Object.keys(snapshot.stores).sort(),['backups','meta','opaque','snapshots']);
 for(const [name,fixture] of Object.entries(expected)){
  assert.deepEqual(Array.from(snapshot.stores[name].keys),fixture.keys,`${name} source keys remain exact`);
  assert.deepEqual(Array.from(snapshot.stores[name].values),fixture.values,`${name} raw values remain exact, including malformed and unknown rows`);
 }

 const unchanged=rawOpen.transaction(['meta','snapshots','backups','opaque'],'readonly');
 const unchangedRows=await Promise.all(Object.keys(expected).map(async name=>{
  const objectStore=unchanged.objectStore(name),[keys,values]=await Promise.all([
   new Promise((resolve,reject)=>{const request=objectStore.getAllKeys();request.onsuccess=()=>resolve(Array.from(request.result));request.onerror=()=>reject(request.error);}),
   new Promise((resolve,reject)=>{const request=objectStore.getAll();request.onsuccess=()=>resolve(Array.from(request.result));request.onerror=()=>reject(request.error);}),
  ]);
  return [name,{keys,values}];
 }));
 await new Promise((resolve,reject)=>{unchanged.oncomplete=resolve;unchanged.onerror=()=>reject(unchanged.error);unchanged.onabort=()=>reject(unchanged.error||new Error('verification read aborted'));});
 for(const [name,rows] of unchangedRows){
  assert.deepEqual(rows.keys,expected[name].keys,`${name} keys are unchanged after export`);
  assert.deepEqual(rows.values,expected[name].values,`${name} values are unchanged after export`);
 }

 transactionReads.length=0;abortNextSnapshot=true;
 await assert.rejects(store.readRawExportSnapshot(),/abort|transaction|request/i,'an aborted archive read rejects instead of producing a partial complete-looking snapshot');
 assert.equal(abortNextSnapshot,false,'the read reached the real four-store transaction');
 assert.deepEqual(transactionReads,[{names:['backups','meta','opaque','snapshots'],mode:'readonly'}]);
});

test('RISK SCALABLE BOARD CODEC: a multi-megabyte Unicode board roundtrips through bounded verified chunks',async()=>{
 const storageV2=loadStorageV2();
 const payload=JSON.stringify({tasks:Array.from({length:3200},(_,index)=>({
  id:'task-'+index,title:'Unicode '+index+' 😀 漢字 '+('\uD800')+' '+('recoverable '.repeat(32)),done:false,
 })),settings:{future:{unknown:true}}});
 assert.ok(Buffer.byteLength(payload,'utf8')>1048576,'fixture exceeds the old single-document ceiling');
 const encoded=await storageV2.encodeSnapshot(payload,{targetBytes:256*1024});
 assert.ok(encoded.chunks.length>4,'chunk count is data-driven rather than fixed to one document');
 assert.equal(encoded.chunkCount,encoded.chunks.length);
 assert.equal(encoded.byteLength,Buffer.byteLength(payload,'utf8'));
 for(const [index,chunk] of encoded.chunks.entries()){
  assert.equal(chunk.index,index);
  assert.ok(chunk.byteLength<=256*1024,'every Firestore chunk stays within the target');
  assert.equal(chunk.byteLength,Buffer.byteLength(chunk.text,'utf8'));
  assert.match(chunk.hash,/^[0-9a-f]{64}$/);
 }
 assert.equal(await storageV2.decodeSnapshot(encoded,encoded.chunks),payload,'UTF-8, emoji, escaped lone surrogates and unknown fields roundtrip byte-exactly');
 const tampered=encoded.chunks.map(row=>({...row}));tampered[1].text+='x';
 await assert.rejects(storageV2.decodeSnapshot(encoded,tampered),/hash|length|corrupt/i,'a damaged generation never becomes a board');
});

test('RISK DEVICE STORAGE V2: migration and head plus recovery commits are atomic, CAS guarded, and preserve legacy bytes',async()=>{
 const {indexedDB}=await import('fake-indexeddb');
 const storageV2=loadStorageV2({indexedDB});
 const store=storageV2.createDeviceStore({indexedDB,crypto:webcrypto,dbName:'chain-scanner-test-'+Date.now()+'-'+Math.random()});
 await store.open();
 const legacyHead=JSON.stringify({tasks:[{id:'old',title:'Legacy 😀'}],future:{kept:true}});
 const unreadableArchive='opaque-old-shell-bytes:\u0000\uD800';
 const legacy={headPayload:legacyHead,sourceFingerprint:'legacy-pair-a',opaqueArchives:[{key:'daily-backups',raw:unreadableArchive}],
  backups:[{id:'manual-old',day:'2026-09-29',at:1,kind:'manual',payload:legacyHead}]};
 const before=structuredClone(legacy);
 const migrated=await store.migrateLegacy(legacy);
 assert.equal(migrated.ok,true);assert.equal(migrated.verified,true);
 assert.deepEqual(legacy,before,'migration never rewrites or deletes live legacy bytes');
 assert.equal((await store.readHead()).payload,legacyHead);
 assert.equal((await store.listBackups()).find(row=>row.id==='manual-old').payload,legacyHead);
 assert.deepEqual(await store.listOpaqueArchives(),legacy.opaqueArchives,'unreadable archives remain byte-exact recovery evidence');

 const next=JSON.stringify({tasks:[{id:'new',title:'Larger board '+('x'.repeat(20000))}],future:{kept:true}});
 const prior=await store.readHead();
 const committed=await store.commitHead({expectedHash:prior.hash,payload:next,account:'owner@example.test',
  backup:{id:'before-replace',day:'2026-09-29',at:2,kind:'before-cloud-local-edit',payload:legacyHead}});
 assert.equal(committed.ok,true);assert.equal((await store.readHead()).payload,next);
 assert.equal((await store.listBackups()).find(row=>row.id==='before-replace').payload,legacyHead,
  'the replacement head and its mandatory recovery copy commit together');

 const stale=await store.commitHead({expectedHash:prior.hash,payload:'{"tasks":[]}',account:'owner@example.test'});
 assert.equal(stale.conflict,true,'a tab cannot publish against a head it did not read');
 assert.equal((await store.readHead()).payload,next,'a failed CAS keeps the newer durable head');

 const collision=await store.commitHead({expectedHash:committed.hash,payload:'{"tasks":[{"id":"lost"}]}',account:'owner@example.test',
  backup:{id:'before-replace',day:'2026-09-29',at:3,kind:'manual',payload:'{"tasks":[{"id":"different"}]}'}});
 assert.equal(collision.error,true,'a conflicting recovery ID aborts rather than replacing old recovery data');
 assert.equal((await store.readHead()).payload,next,'the same transaction abort preserves the prior head');
 assert.equal((await store.listBackups()).find(row=>row.id==='before-replace').payload,legacyHead);
 await store.close();
});

test('RISK DEVICE STORAGE V2: unreferenced immutable snapshots retire while head and recovery references remain exact',async()=>{
 const {indexedDB}=await import('fake-indexeddb'),dbName='chain-scanner-gc-'+Date.now()+'-'+Math.random();
 const storageV2=loadStorageV2({indexedDB}),store=storageV2.createDeviceStore({indexedDB,crypto:webcrypto,dbName});
 await store.open();
 const first='{"tasks":[{"id":"first"}]}',second='{"tasks":[{"id":"second"}]}',third='{"tasks":[{"id":"third"}]}';
 await store.migrateLegacy({headPayload:first,backups:[],opaqueArchives:[]});
 let head=await store.readHead();
 let result=await store.commitHead({expectedHash:head.hash,payload:second,backup:{id:'kept-first',day:'2026-09-29',at:1,kind:'manual',payload:first}});
 result=await store.commitHead({expectedHash:result.hash,payload:third});
 const openDb=()=>new Promise((resolve,reject)=>{const request=indexedDB.open(dbName);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});
 const snapshotPayloads=async()=>{const db=await openDb();try{return await new Promise((resolve,reject)=>{const request=db.transaction('snapshots').objectStore('snapshots').getAll();request.onsuccess=()=>resolve(request.result.map(row=>row.payload));request.onerror=()=>reject(request.error);});}finally{db.close();}};
 assert.deepEqual(new Set(await snapshotPayloads()),new Set([first,third]),'the live head and referenced recovery remain, while an unreferenced intermediate head retires');
 assert.equal(await store.deleteBackup('kept-first',{payload:first,allowedKinds:['manual']}),true);
 assert.deepEqual(await snapshotPayloads(),[third],'deleting the last recovery reference retires its immutable payload but never the head');
 await store.close();
});

function loadCloudV2(){
 const sandbox=vm.createContext({console,crypto:webcrypto,TextEncoder,TextDecoder,Uint8Array,setTimeout,clearTimeout,structuredClone});
 sandbox.globalThis=sandbox;
 for(const file of ['device-store-v2.js','cloud-store-v2.js']){
  assert.ok(fs.existsSync(path.join(__dirname,file)),'the scalable cloud module must ship with the offline app: '+file);
  vm.runInContext(fs.readFileSync(path.join(__dirname,file),'utf8'),sandbox,{filename:file});
 }
 return sandbox.ChainCloudV2;
}

function cloudV2Payload(label='large'){
 return JSON.stringify({tasks:Array.from({length:3600},(_,index)=>({id:`${label}-${index}`,
  title:`${label} ${index} 😀 ${'recoverable '.repeat(32)}`,done:false})),settings:{future:{kept:true}}});
}

function cloudV2Adapter(){
 const roots=new Map(),generations=new Map();let crashAfter=Infinity,crashed=false,beforePublish=null,onGenerationRead=null;
 const key=(uid,id)=>uid+'/'+id,clone=value=>value==null?value:structuredClone(value);
 const api={roots,generations,
  setCrashAfter(value){crashAfter=value;crashed=false},setBeforePublish(fn){beforePublish=fn},setGenerationRead(fn){onGenerationRead=fn},
  async readRoot(uid){return clone(roots.get(uid)||null)},
  async beginGeneration(uid,id,header){const k=key(uid,id),existing=generations.get(k);if(existing)return clone(existing.header);generations.set(k,{header:clone(header),chunks:new Map()});return clone(header)},
  async readGeneration(uid,id){if(onGenerationRead){const fn=onGenerationRead;onGenerationRead=null;await fn({uid,id,api});}return clone(generations.get(key(uid,id))?.header||null)},
  async readChunks(uid,id){return [...(generations.get(key(uid,id))?.chunks.values()||[])].sort((a,b)=>a.index-b.index).map(clone)},
  async writeChunks(uid,id,chunks){const generation=generations.get(key(uid,id));if(!generation)throw Error('missing generation');for(const chunk of chunks){
   if(!crashed&&generation.chunks.size>=crashAfter){crashed=true;throw Error('simulated upload crash');}
   const old=generation.chunks.get(chunk.index);if(old&&JSON.stringify(old)!==JSON.stringify(chunk))throw Error('immutable chunk mismatch');if(!old)generation.chunks.set(chunk.index,clone(chunk));
  }},
  async sealGeneration(uid,id,header){const generation=generations.get(key(uid,id));if(!generation)throw Error('missing generation');generation.header={...clone(header),state:'sealed'};return clone(generation.header)},
  async publishGeneration(uid,id,{baseRev,updatedAt,stillCurrent}){if(beforePublish)await beforePublish();if(stillCurrent&&!stillCurrent())return {cancelled:true};const generation=generations.get(key(uid,id));const current=roots.get(uid)||null,rev=current?.rev||0;if(generation?.header.state!=='sealed')return {error:true,code:'unsealed'};if(rev!==baseRev)return {conflict:true,rev};const root={schemaVersion:2,rev:rev+1,activeGeneration:id,previousGeneration:current?.activeGeneration||null,updatedAt};generation.header={...generation.header,state:'published',publishedAt:Date.now()};roots.set(uid,root);return {ok:true,rev:root.rev,root:clone(root)}},
  async listGenerations(uid){return [...generations].filter(([k])=>k.startsWith(uid+'/')).map(([k,value])=>({id:k.slice(uid.length+1),...clone(value.header)}))},
  async markDeleting(uid,id,protectedIds=[]){const root=roots.get(uid),generation=generations.get(key(uid,id));if(!generation||root?.activeGeneration===id||root?.previousGeneration===id||protectedIds.includes(id))return false;generation.header={...generation.header,state:'deleting'};return true},
  async deleteChunks(uid,id){const generation=generations.get(key(uid,id));if(generation?.header.state!=='deleting')throw Error('generation is not deleting');generation.chunks.clear()},
  async deleteGeneration(uid,id){const k=key(uid,id),generation=generations.get(k);if(generation?.header.state!=='deleting'||generation.chunks.size)throw Error('generation is not empty');generations.delete(k)},
 };
 return api;
}

test('RISK CLOUD V2: a multi-megabyte board publishes only after verified chunks and pulls byte-exactly',async()=>{
 const cloudV2=loadCloudV2(),adapter=cloudV2Adapter(),store=cloudV2.createCloudStore({adapter,crypto:webcrypto,targetBytes:256*1024,batchSize:3});
 const payload=cloudV2Payload('published');assert.ok(Buffer.byteLength(payload,'utf8')>1048576);
 const pushed=await store.push('owner',payload,123,0);
 assert.equal(pushed.ok,true);assert.equal(pushed.rev,1);
 const root=adapter.roots.get('owner');assert.equal(root.schemaVersion,2);assert.equal(Object.hasOwn(root,'payload'),false,'v2 root never carries the whole board');
 const generation=adapter.generations.get('owner/'+root.activeGeneration);
 assert.equal(generation.header.state,'published');assert.ok(generation.chunks.size>4);
 const pulled=await store.pull('owner');assert.equal(pulled.payload,payload);assert.equal(pulled.rev,1);
});

test('RISK CLOUD V2: crash resume, concurrent revisions, and account cancellation never publish partial data',async()=>{
 const cloudV2=loadCloudV2(),adapter=cloudV2Adapter(),store=cloudV2.createCloudStore({adapter,crypto:webcrypto,targetBytes:64*1024,batchSize:2});
 const base=await store.push('owner',JSON.stringify({tasks:[{id:'base'}]}),1,0);assert.equal(base.ok,true);
 adapter.setCrashAfter(2);
 const interrupted=await store.push('owner',cloudV2Payload('resume'),2,1);
 assert.equal(interrupted.error,true);assert.ok(interrupted.generationId);assert.equal(adapter.roots.get('owner').rev,1,'partial chunks are unreachable');
 adapter.setCrashAfter(Infinity);
 const resumed=await store.push('owner',cloudV2Payload('resume'),2,1,{generationId:interrupted.generationId});
 assert.equal(resumed.ok,true);assert.equal((await store.pull('owner')).payload,cloudV2Payload('resume'));

 const first=await store.push('owner',JSON.stringify({tasks:[{id:'winner'}]}),3,2);
 const stale=await store.push('owner',JSON.stringify({tasks:[{id:'loser'}]}),3,2);
 assert.equal(first.ok,true);assert.equal(stale.conflict,true);assert.equal(JSON.parse((await store.pull('owner')).payload).tasks[0].id,'winner');
 let current=true;adapter.setBeforePublish(()=>{current=false});
 const cancelled=await store.push('owner',JSON.stringify({tasks:[{id:'wrong-account'}]}),4,3,{stillCurrent:()=>current});
 assert.equal(cancelled.cancelled,true);assert.equal(JSON.parse((await store.pull('owner')).payload).tasks[0].id,'winner');
});

test('RISK CLOUD V2: corrupt active data fails closed, manifest races retry, and garbage collection keeps recovery generations',async()=>{
 const cloudV2=loadCloudV2(),adapter=cloudV2Adapter(),store=cloudV2.createCloudStore({adapter,crypto:webcrypto,targetBytes:16*1024,batchSize:2});
 for(let rev=0;rev<4;rev++)assert.equal((await store.push('owner',JSON.stringify({tasks:[{id:'rev-'+(rev+1)}]}),rev+1,rev)).ok,true);
 const root=adapter.roots.get('owner'),protectedGeneration=[...adapter.generations.keys()].map(key=>key.split('/')[1]).find(id=>id!==root.activeGeneration&&id!==root.previousGeneration);
 const pendingGeneration=[...adapter.generations.keys()].map(key=>key.split('/')[1]).find(id=>id!==root.activeGeneration&&id!==root.previousGeneration&&id!==protectedGeneration);
 for(const [key,generation] of adapter.generations)if(![root.activeGeneration,root.previousGeneration].some(id=>key.endsWith('/'+id)))generation.header.createdAt=Date.now()-8*86400000;
 await adapter.beginGeneration('owner','young-other-device',{schemaVersion:2,state:'staging',encoding:'utf8',chunkCount:1,byteLength:2,hash:'a'.repeat(64),baseRev:4,createdAt:Date.now()});
 await store.collectGarbage('owner',{pendingGenerationIds:[pendingGeneration]});
 assert.ok(adapter.generations.has('owner/'+root.activeGeneration));assert.ok(adapter.generations.has('owner/'+root.previousGeneration));assert.ok(adapter.generations.has('owner/'+pendingGeneration));
 assert.equal(adapter.generations.has('owner/'+protectedGeneration),false,'unreferenced nonpending generations are retired');
 assert.ok(adapter.generations.has('owner/young-other-device'),'a recent staged upload from another device is never collected mid-publication');

 const previous=root.previousGeneration,active=root.activeGeneration;
 adapter.setGenerationRead(({api})=>{api.roots.set('owner',{...api.roots.get('owner'),activeGeneration:previous,previousGeneration:active,rev:5});});
 assert.equal(JSON.parse((await store.pull('owner')).payload).tasks[0].id,'rev-3','a root change during read restarts from the new active generation');
 const newRoot=adapter.roots.get('owner'),generation=adapter.generations.get('owner/'+newRoot.activeGeneration),firstChunk=generation.chunks.get(0);
 generation.chunks.set(0,{...firstChunk,text:firstChunk.text+'damage'});
 const corrupt=await store.pull('owner');assert.equal(corrupt.error,true);assert.match(corrupt.code,/corrupt|hash/i);
 assert.notEqual(JSON.parse(adapter.generations.get('owner/'+newRoot.previousGeneration).chunks.get(0).text).tasks[0].id,undefined,
  'the previous generation stays available for explicit recovery but is never silently made current');
});

async function decisionBackend146(artifacts,db,F,uid='owner',{beforePublication=null}={}){
 const pending=new Set(),auth={currentUser:{uid,email:'e@example.com'}},events=[];
 const host=value=>Array.isArray(value)?Array.from(value,host):value?.constructor?.name==='Object'?Object.fromEntries(Object.entries(value).map(([k,v])=>[k,host(v)])):value;
 const writer=(target,onWrite=null)=>new Proxy(target,{get(object,key){const value=object[key];return typeof value!=='function'?value:(...args)=>{if(['set','update'].includes(key))onWrite?.(args[0]);return Reflect.apply(value,object,['set','update'].includes(key)?args.map(host):args);};}});
 const sdk={...F,getFirestore:()=>db,writeBatch:(...args)=>writer(F.writeBatch(...args))};
 for(const key of ['getDoc','getDocs','runTransaction'])sdk[key]=(...args)=>{
  if(key==='runTransaction'){const fn=args[1];args[1]=async tx=>{
   let publishes=false;
   const result=await fn(writer(tx,ref=>{if(ref.path===`users/${uid}`)publishes=true;}));
   if(publishes)await beforePublication?.();
   return result;
  };}
  const result=F[key](...args);pending.add(result);result.then(()=>pending.delete(result),()=>pending.delete(result));return result;
 };
 const window={FIREBASE_CONFIG:{apiKey:'emulator-only'},CLOUD_SYNC_TIMEOUT_MS:5000,dispatchEvent:event=>events.push(event)};
 const A={getAuth:()=>auth,setPersistence:async()=>{},browserLocalPersistence:{},onAuthStateChanged:(_,fn)=>fn(auth.currentUser)};
 const context=vm.createContext({window,crypto:webcrypto,TextEncoder,TextDecoder,Uint8Array,structuredClone,console,setTimeout,clearTimeout,CustomEvent:class{},__modules:[{initializeApp:()=>({})},A,sdk]});
 for(const [file,code] of [['device-store-v2.js',artifacts.storage],['cloud-store-v2.js',artifacts.cloud]])vm.runInContext(code,context,{filename:file});
 window.ChainStorageV2=context.ChainStorageV2;window.ChainCloudV2=context.ChainCloudV2;
 const module=artifacts.html.match(/<script type="module">([\s\S]*?)<\/script>/)[1].replace(/const \[appMod, A, F\] = await Promise\.all\(\[[\s\S]*?\]\);/,'const [appMod,A,F]=globalThis.__modules;');
 await vm.runInContext(`(async()=>{${module}\n})()`,context);
 assert.equal(window.CloudSync.ready,true);
 return {CS:window.CloudSync,async drain(){for(let idle=0;idle<2;){if(pending.size){idle=0;await Promise.allSettled([...pending]);}else idle++;await flush();}}};
}
function decisionCandidate146(){return {html,cloud:fs.readFileSync(path.join(__dirname,'cloud-store-v2.js'),'utf8'),storage:fs.readFileSync(path.join(__dirname,'device-store-v2.js'),'utf8')};}

test('Firestore rules: real pinned writer reads decision authority then holds its ordinary app edit without erasing it', {skip:!process.env.FIRESTORE_EMULATOR_HOST}, async t=>{
 const {SUPPORTED_RELEASE,readReleasedClient}=await import('./scripts/backward-compatibility.mjs');
 const {initializeTestEnvironment}=await import('@firebase/rules-unit-testing'),F=await import('firebase/firestore');
 const floor=readReleasedClient(__dirname,SUPPORTED_RELEASE),candidate=decisionCandidate146();
 for(const schedule of ['natural','candidate','historical'])await t.test(schedule,async t=>{
 const env=await initializeTestEnvironment({projectId:`demo-decision-mixed-146-${schedule}`,firestore:{rules:fs.readFileSync(path.join(__dirname,'firestore.rules'),'utf8')}}),handles=[];
 let publicationReady=null;
 try{
  const old=await decisionBackend146(floor,env.authenticatedContext('owner').firestore(),F,'owner',{beforePublication:()=>publicationReady?.('historical')}),
   next=await decisionBackend146(candidate,env.authenticatedContext('owner').firestore(),F,'owner',{beforePublication:()=>publicationReady?.('candidate')});handles.push(old,next);
  const f=await decisionMixedActionsApp146();t.after(()=>{f.ctx.window.CloudSync.user=null;vm.runInContext('clearCloudRetry();clearTimeout(cloudTimer)',f.ctx);});
  const plain=JSON.stringify(f.h.remoteState()),decided=f.ctx.cloudPayload();
  assert.equal((await old.CS.push(plain,1,0)).ok,true,'pinned writer seeds an ordinary board');
  assert.equal((await next.CS.pull()).payload,plain);
  assert.equal((await next.CS.push(plain,2,1)).ok,true,'upgraded ordinary publication remains readable by floor');
  const oldRead=await old.CS.pull(),oldReadAccount=old.CS.user;assert.equal(oldRead.payload,plain);
  // Both real transactions stage their publication against revision2 before
  // the selected winner commits. The loser may then conflict or be denied by
  // the rules; neither outcome may alter the exact winning root.
  let releaseLoser,releasePrepared;
  if(schedule!=='natural'){
   let prepared=0;
   const bothPrepared=new Promise(resolve=>{releasePrepared=resolve;}),winnerAcknowledged=new Promise(resolve=>{releaseLoser=resolve;});
   publicationReady=async side=>{if(++prepared===2)releasePrepared();await bothPrepared;if(side!==schedule)await winnerAcknowledged;};
  }
  const activating=next.CS.push(decided,3,2),legacy=old.CS.push(plain,3,2);
  // An operation failing before staging must release the peer for a concrete
  // failed assertion rather than leave the test waiting on its barrier.
  if(releasePrepared)for(const operation of [activating,legacy])operation.then(releasePrepared,releasePrepared);
  if(releaseLoser)(schedule==='candidate'?activating:legacy).then(releaseLoser,releaseLoser);
  const [activated,competing]=await Promise.all([activating,legacy]);publicationReady=null;
  assert.equal(Number(activated.ok===true)+Number(competing.ok===true),1,'CAS admits one activation-racing writer');
  const winner=activated.ok?activated:competing,loser=activated.ok?competing:activated,losingClient=activated.ok?old.CS:next.CS;
  const raceFacts=JSON.stringify({schedule,activated,competing,status:losingClient.status,code:losingClient.errorCode});
  assert.ok(loser.conflict===true||(loser.error===true&&loser.code==='permission-denied'),
   'activation races either conflict or safely fence the losing writer: '+raceFacts);
  if(schedule!=='natural')assert.equal((schedule==='candidate'?activated:competing).ok,true,'the real SDK commits the scheduled winner');
  if(loser.error){assert.equal(losingClient.status,'error');assert.equal(losingClient.errorStage,'push');assert.equal(losingClient.errorCode,'permission-denied');}
  else assert.equal(loser.rev,3,'a conflict identifies the actual winning revision');
  const root=(await F.getDocFromServer(F.doc(env.authenticatedContext('owner').firestore(),'users/owner'))).data();
  assert.equal(root.rev,3);assert.equal(winner.rev,3);assert.equal(root.activeGeneration,winner.generationId);
  const winningHeader=(await F.getDocFromServer(F.doc(env.authenticatedContext('owner').firestore(),'users','owner','generations',root.activeGeneration))).data();
  assert.equal(winningHeader.hash,createHash('sha256').update(activated.ok?decided:plain,'utf8').digest('hex'),'real SDK fixture publication must use the independent UTF8 digest');
  assert.equal(root.decisionCapability,activated.ok?1:undefined,'only an actual winning activation installs the fence');
  const winning=await next.CS.pull();assert.equal(winning.rev,3);assert.equal(winning.payload,activated.ok?decided:plain,'the losing transaction cannot replace any winning bytes');
  assert.equal(f.ctx.cloudPayload(),decided);assert.equal(f.ctx.state.syncDirty,true,'the actual-app decision source stays pending');
  assert.equal(JSON.stringify(JSON.parse(f.storage.getItem(SYNC_STORE_KEY)).decisionEvents),JSON.stringify(JSON.parse(decided).decisionEvents),
   'all candidate facts stay exact and durable even when activation loses');
  // Once the winning revision is visible, either stale writer must return a
  // revision conflict without publishing even a partial generation.
  for(const [client,payload] of [[next.CS,decided],[old.CS,plain]]){
   const stale=await client.push(payload,3,2);assert.equal(stale.conflict,true);assert.equal(stale.rev,3);
  }
  const unchanged=await next.CS.pull();assert.equal(unchanged.rev,winning.rev);assert.equal(unchanged.payload,winning.payload);
  if(!activated.ok){const current=await next.CS.pull();assert.equal((await next.CS.push(decided,4,current.rev)).ok,true);}
  const exact=await next.CS.pull();assert.equal(exact.payload,decided);assert.equal(exact.rev,activated.ok?3:4);
  assert.equal((await old.CS.pull()).payload,decided,'pinned reader accepts additional root capability');
  // Reopen the pinned reader's last durable plain-board read, witnessed above.
  // The action producer's separate synthetic revision4 must not attest that
  // this old device already read the later real activation at revision4.
  const oldLocal=JSON.stringify({...JSON.parse(oldRead.payload),syncRev:oldRead.rev,syncAccount:oldReadAccount,syncDirty:false});
  const oldApp=await loadApp({appSource:extractAppScript(floor.html),seedStorage:{[SYNC_STORE_KEY]:oldLocal,[LOCAL_HEAD_KEY]:oldLocal},cloudSyncFactory:()=>old.CS});
  let updates=0;oldApp.ctx.window.checkForAppUpdate=async()=>{updates++;};
  t.after(()=>{old.CS.user=null;vm.runInContext('clearCloudRetry();clearTimeout(cloudTimer)',oldApp.ctx);});
  await oldApp.ctx.cloudPull();
  assert.equal(JSON.stringify(oldApp.ctx.state.decisionEvents),JSON.stringify(JSON.parse(decided).decisionEvents),'the immutable historical app carries every comparison, choice and Undo fact exactly');
  assert.equal(oldApp.ctx.state.tasks.find(task=>task.id==='bench').title,'Mixed retained benchmark title','the old reader opens the effective retained current choice');
  assert.deepEqual(mixedSharedOutcome146(oldApp.ctx.state),f.mixed.shared,'the immutable historical reader carries the new typed shared outcomes without overwriting them');
  oldApp.ctx.addTask('Legacy independent edit held for safe update');await oldApp.ctx.persist();oldApp.ctx.cloudPushNow();await syncSettle(180);
  assert.equal(old.CS.errorCode,'permission-denied','the real fixed historical manifest is denied');
  assert.equal(oldApp.ctx.state.syncDirty,true);assert.equal(oldApp.shim.document.getElementById('syncBtn').textContent,'☁ error');assert.ok(updates>=1,'historical app enters its established compatible-shell recovery');
  const before=await next.CS.pull();assert.equal(before.payload,exact.payload);assert.equal(before.rev,exact.rev);
  oldApp.shim.window.dispatchEvent({type:'focus'});oldApp.ctx.cloudPushNow();await syncSettle(50);
  const after=await next.CS.pull();assert.equal(after.payload,exact.payload);assert.equal(after.rev,exact.rev,'focus does not spin rejected writes');
  assert.ok(oldApp.ctx.state.tasks.some(task=>task.title==='Legacy independent edit held for safe update'),'unpublished legacy edit stays recoverable');
 }finally{await Promise.all(handles.map(handle=>handle.drain()));await env.cleanup();}
 });
});

test('Firestore rules: first decision against released rules stays exact and pending until rules-first rollout then retry', {skip:!process.env.FIRESTORE_EMULATOR_HOST},async t=>{
 const {SUPPORTED_RELEASE,readReleasedClient}=await import('./scripts/backward-compatibility.mjs');
 const {initializeTestEnvironment}=await import('@firebase/rules-unit-testing'),F=await import('firebase/firestore');
 const floor=readReleasedClient(__dirname,SUPPORTED_RELEASE),projectId='demo-decision-rollout-146';
 const env=await initializeTestEnvironment({projectId,firestore:{rules:floor.rules}});let upgraded;
 const handle=await decisionBackend146(decisionCandidate146(),env.authenticatedContext('owner').firestore(),F);
 try{
  const f=await decisionRecoveryApp146();t.after(()=>{f.ctx.window.CloudSync.user=null;vm.runInContext('clearCloudRetry();clearTimeout(cloudTimer)',f.ctx);});
  const plain=JSON.stringify(f.h.remoteState());assert.equal((await handle.CS.push(plain,1,0)).ok,true);
  const app=await loadApp({seedStorage:{[SYNC_STORE_KEY]:plain,[LOCAL_HEAD_KEY]:plain},cloudSyncFactory:()=>handle.CS});
  t.after(()=>{handle.CS.user=null;vm.runInContext('clearCloudRetry();clearTimeout(cloudTimer)',app.ctx);});
  app.shim.window.CLOUD_PUSH_DELAY_MS=2;await app.ctx.cloudPull();handle.CS.ready=false;app.ctx.renderScan();app.ctx.onAction('no',{dataset:{candidate:'candidate',benchmark:'bench'}});await recordMixedDecisionActions146(app);await app.ctx.persist();handle.CS.ready=true;
  const evidence=JSON.stringify(app.ctx.state.decisionEvents),ratings=JSON.stringify(app.ctx.state.tasks.map(task=>[task.id,task.mu,task.sigma]));
  const shared=mixedSharedOutcome146(app.ctx.state);
  const outcomes=JSON.stringify({chain:app.ctx.state.chain,title:app.ctx.state.tasks.find(task=>task.id==='bench').title,passId:app.ctx.state.passId,scanMode:app.ctx.state.scanMode,chance:app.ctx.state.chance});
  assert.deepEqual([...new Set(app.ctx.state.decisionEvents.map(event=>event.kind))].sort(),['comparison','current-choice','no','undo']);
  assert.deepEqual([...new Set(app.ctx.state.decisionEvents.filter(event=>event.kind==='comparison').map(event=>event.action))].sort(),['dislodge','dot','yes']);
  app.ctx.cloudPushNow();await syncSettle(160);
  assert.equal(handle.CS.errorCode,'permission-denied');assert.equal(app.ctx.state.syncDirty,true);assert.equal(JSON.stringify(app.ctx.state.decisionEvents),evidence);
  assert.equal(JSON.stringify(JSON.parse(app.shim.localStorage.getItem(SYNC_STORE_KEY)).decisionEvents),evidence,'rejected first decision stays durable');
  assert.equal((await handle.CS.pull()).payload,plain,'released rules never accept an unfenced fallback');
  upgraded=await initializeTestEnvironment({projectId,firestore:{rules:fs.readFileSync(path.join(__dirname,'firestore.rules'),'utf8')}});
  await app.ctx.onAction('sync-retry',{});await syncSettle(600);
  const published=await handle.CS.pull();assert.equal(JSON.stringify(JSON.parse(published.payload).decisionEvents),evidence);
  assert.equal(JSON.stringify(app.ctx.state.tasks.map(task=>[task.id,task.mu,task.sigma])),ratings,'retry does not retrain the comparison');
  assert.equal(app.ctx.state.syncDirty,false);assert.equal(app.shim.document.getElementById('syncBtn').textContent,'☁ synced');
  const cloud=JSON.parse(published.payload);
  assert.deepEqual(mixedSharedOutcome146(cloud),shared,'rules-first retry preserves every typed shared preference, scene field and context definition');
  assert.equal(JSON.stringify({chain:cloud.chain,title:cloud.tasks.find(task=>task.id==='bench').title,passId:cloud.passId,scanMode:cloud.scanMode,chance:cloud.chance}),outcomes,'rules-first Retry preserves actual chosen fields and scoped Undo/pass outcomes as well as learning and raw facts');
 }finally{await handle.drain();await upgraded?.cleanup();await env.cleanup();}
});

test('Firestore rules: decision capability activates atomically and denies an omitting historical manifest', {skip:!process.env.FIRESTORE_EMULATOR_HOST},async()=>{
 const {assertFails,assertSucceeds,initializeTestEnvironment}=await import('@firebase/rules-unit-testing');
 const {doc,setDoc,getDoc,serverTimestamp}=await import('firebase/firestore');
 const env=await initializeTestEnvironment({projectId:'demo-decision-capability-146',firestore:{rules:fs.readFileSync(path.join(__dirname,'firestore.rules'),'utf8')}});
 try{
  const db=env.authenticatedContext('owner').firestore(),root=doc(db,'users/owner');
  await env.withSecurityRulesDisabled(async context=>{
   for(const id of ['plain','decision','omission','retained'])await setDoc(doc(context.firestore(),'users/owner/generations/'+id),{schemaVersion:2,state:'sealed'});
  });
  const manifest=(rev,activeGeneration,previousGeneration,extra={})=>({schemaVersion:2,rev,activeGeneration,previousGeneration,updatedAt:rev,serverUpdatedAt:serverTimestamp(),...extra});
  await assertSucceeds(setDoc(root,manifest(1,'plain',null)));
  await assertSucceeds(setDoc(root,manifest(2,'decision','plain',{decisionCapability:1})));
  assert.equal((await getDoc(root)).data().decisionCapability,1);
  await assertFails(setDoc(root,manifest(3,'omission','decision')),'fixed-manifest historical publication must not remove acknowledged authority');
  assert.equal((await getDoc(root)).data().activeGeneration,'decision','denied legacy publication leaves exact active authority');
  await assertFails(setDoc(root,manifest(3,'omission','decision',{decisionCapability:2})));
  await assertSucceeds(setDoc(root,manifest(3,'retained','decision',{decisionCapability:1})));
 }finally{await env.cleanup();}
});

test('Firestore rules: v2 chunks are owner-only, immutable, sealed before publish, and old clients fail closed', {skip:!process.env.FIRESTORE_EMULATOR_HOST}, async()=>{
 const {assertFails,assertSucceeds,initializeTestEnvironment}=await import('@firebase/rules-unit-testing');
 const {doc,getDoc,setDoc,updateDoc,deleteDoc,serverTimestamp}=await import('firebase/firestore');
 const rules=fs.readFileSync(path.join(__dirname,'firestore.rules'),'utf8');
 const env=await initializeTestEnvironment({projectId:'demo-chain-scanner-v2',firestore:{rules}});
 try{
  const alice=env.authenticatedContext('alice').firestore(),bob=env.authenticatedContext('bob').firestore();
  const root=doc(alice,'users/alice'),generation=id=>doc(alice,`users/alice/generations/${id}`),chunk=(id,index)=>doc(alice,`users/alice/generations/${id}/chunks/${index}`);
  const header=(state='staging')=>({schemaVersion:2,state,encoding:'utf8',chunkCount:1,byteLength:13,hash:'a'.repeat(64),baseRev:0,createdAt:serverTimestamp()});
  const chunkData={index:0,text:'{"tasks":[]}',byteLength:12,hash:'b'.repeat(64)};
  await assertSucceeds(setDoc(generation('g1'),header()));await assertSucceeds(setDoc(chunk('g1',0),chunkData));
  await assertFails(setDoc(root,{schemaVersion:2,rev:1,activeGeneration:'g1',previousGeneration:null,updatedAt:1,serverUpdatedAt:serverTimestamp()}));
  await assertSucceeds(updateDoc(generation('g1'),{state:'sealed',sealedAt:serverTimestamp()}));
  await assertSucceeds(setDoc(root,{schemaVersion:2,rev:1,activeGeneration:'g1',previousGeneration:null,updatedAt:1,serverUpdatedAt:serverTimestamp()}));
  await assertFails(setDoc(root,{payload:'{"tasks":[]}',updatedAt:2,rev:2,serverUpdatedAt:serverTimestamp()}));
  await assertFails(updateDoc(chunk('g1',0),{text:'changed'}));await assertFails(deleteDoc(chunk('g1',0)));
  await assertFails(getDoc(doc(bob,'users/alice/generations/g1')));await assertFails(setDoc(doc(bob,'users/alice/generations/x'),header()));

  for(const [id,baseRev] of [['g2',1],['g3',2]]){
   await assertSucceeds(setDoc(generation(id),{...header(),baseRev}));await assertSucceeds(setDoc(chunk(id,0),chunkData));
   await assertSucceeds(updateDoc(generation(id),{state:'sealed',sealedAt:serverTimestamp()}));
   const current=(await getDoc(root)).data();
   await assertSucceeds(setDoc(root,{schemaVersion:2,rev:baseRev+1,activeGeneration:id,previousGeneration:current.activeGeneration,updatedAt:baseRev+1,serverUpdatedAt:serverTimestamp()}));
  }
  await assertFails(updateDoc(generation('g2'),{state:'deleting',deletingAt:serverTimestamp()}),'the previous generation remains protected');
  await assertSucceeds(updateDoc(generation('g1'),{state:'deleting',deletingAt:serverTimestamp()}));
  await assertSucceeds(deleteDoc(chunk('g1',0)));await assertSucceeds(deleteDoc(generation('g1')));
  await assertFails(deleteDoc(root));
 }finally{await env.cleanup();}
});

test('RISK SCALABLE LOCAL BOARD: a multi-megabyte legacy board migrates without rewriting source bytes and survives edit Undo and offline reload',async()=>{
 const {indexedDB}=await import('fake-indexeddb');
 const dbName='chain-scanner-app-large-'+Date.now()+'-'+Math.random();
 const large=syncState({tasks:[syncTask('legacy-large','Legacy large board')],syncRev:0,syncAccount:null,syncDirty:true});
 large.futureBoardData={unknown:true,blob:'😀 recoverable '.repeat(100000)};
 const raw=JSON.stringify(large);
 assert.ok(Buffer.byteLength(raw,'utf8')>1048576,'production fixture exceeds Firestore and common localStorage headroom');
 const values=new Map([[LOCAL_HEAD_KEY,raw],[SYNC_STORE_KEY,raw],[LOCAL_BACKUPS_KEY,'opaque legacy archive bytes']]);
 const storage={
  getItem:key=>values.has(key)?values.get(key):null,
  setItem(key,value){value=String(value);if(value.length>300000)throw Object.assign(Error('quota'),{name:'QuotaExceededError'});values.set(key,value);},
  removeItem:key=>values.delete(key),
 };
 const first=await loadApp({sharedStorage:storage,indexedDBProvider:indexedDB,deviceDbName:dbName});
 assert.equal(first.ctx.deviceStorageActive(),true,'verified IndexedDB becomes the durable head authority');
 assert.equal(storage.getItem(SYNC_STORE_KEY),raw,'migration never rewrites the old shell board bytes');
 assert.equal(storage.getItem(LOCAL_BACKUPS_KEY),'opaque legacy archive bytes','unreadable legacy archives remain byte-exact');
 first.ctx.addTask('Saved beyond localStorage quota');
 assert.equal(await first.ctx.persist(),true);
 assert.ok((await first.shim.window.ScannerDeviceStore.readHead()).payload.includes('Saved beyond localStorage quota'));
 first.ctx.undo();assert.equal(await first.ctx.persist(),true,'Undo itself is a durable scalable save');

 const reopened=await loadApp({sharedStorage:storage,indexedDBProvider:indexedDB,deviceDbName:dbName});
 assert.equal(reopened.ctx.state.futureBoardData.blob,large.futureBoardData.blob,'unknown large board fields survive cold reload');
 assert.equal(reopened.ctx.state.tasks.some(task=>task.title==='Saved beyond localStorage quota'),false,'the durable Undo survives offline reload');
 assert.equal(storage.getItem(SYNC_STORE_KEY),raw,'a v2 save that cannot mirror into localStorage preserves the last legacy copy');
});

