 const a=initial.ctx.addTask('Bootstrap'),b=initial.ctx.addTask('Other');a.createdAt=1;b.createdAt=2;initial.ctx.startScan();await initial.ctx.persist();await initial.ctx.cloudPushNow();await syncSettle(80);
